INSERT INTO system_vocabulary_words (id, set_id, topic_id, part_id, word, ipa, cefr, part_of_speech, meaning_vi, definition_en, example_en, example_vi, example_toeic, audio_us, audio_uk, image_url, synonyms, antonyms, phrases, confusables, word_family, audio_voices, note_vi, toeic_topic, difficulty_level, order_index) VALUES
('1c51c189-b8f8-5471-b044-dc95445b2e29', '0a4ec2d7-01c5-5457-a414-6530a08abf22', '04d0f65f-27b6-5a5f-bebd-c21a6e729b10', '5cfe7e21-e9bf-519c-a99f-264aa1c3d369', 'cynical', '/ˈsɪnɪkl/', 'B2', 'adjective', 'Tin rằng con người chỉ hành động vì lợi ích cá nhân và không tin vào sự chân thành.', 'believing that people only care about themselves and are not honest or sincere in actions.', 'After years in politics, he became cynical about the motives of most public figures.', 'Sau nhiều năm làm chính trị, ông trở nên hoài nghi về động cơ của hầu hết các nhân vật công chúng.', '{\"en\": \"Some employees are cynical about the company\'s new policy, fearing it will reduce their benefits.\", \"vi\": \"Một số nhân viên hoài nghi về chính sách mới của công ty, sợ rằng nó sẽ giảm phúc lợi.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/cynical-ljspeech-a1a2aafe.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/cynical-cori-a1a2aafe.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/cynical-2dc4843d.webp', '[\"skeptical\", \"distrustful\"]', '[\"optimistic\", \"trusting\"]', '[{\"phrase\": \"cynical view\", \"meaning\": \"quan điểm hoài nghi\"}, {\"phrase\": \"cynical attitude\", \"meaning\": \"thái độ hoài nghi\"}]', '[{\"word\": \"critical\", \"note_vi\": \"Critical là hay chỉ trích, cynical là hoài nghi về động cơ.\"}]', '[{\"pos\": \"noun\", \"word\": \"cynic\"}, {\"pos\": \"noun\", \"word\": \"cynicism\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/cynical-cori-a1a2aafe.mp3\", \"/storage/v1/object/public/pronunciation/v2/cynical-aru0-a1a2aafe.mp3\", \"/storage/v1/object/public/pronunciation/v2/cynical-aru5-a1a2aafe.mp3\", \"/storage/v1/object/public/pronunciation/v2/cynical-aru6-a1a2aafe.mp3\", \"/storage/v1/object/public/pronunciation/v2/cynical-aru10-a1a2aafe.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/cynical-aru9-a1a2aafe.mp3\", \"/storage/v1/object/public/pronunciation/v2/cynical-aru3-a1a2aafe.mp3\", \"/storage/v1/object/public/pronunciation/v2/cynical-aru7-a1a2aafe.mp3\", \"/storage/v1/object/public/pronunciation/v2/cynical-aru8-a1a2aafe.mp3\", \"/storage/v1/object/public/pronunciation/v2/cynical-aru2-a1a2aafe.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/cynical-ljspeech-a1a2aafe.mp3\", \"/storage/v1/object/public/pronunciation/v2/cynical-lt408-a1a2aafe.mp3\", \"/storage/v1/object/public/pronunciation/v2/cynical-lt138-a1a2aafe.mp3\", \"/storage/v1/object/public/pronunciation/v2/cynical-lt624-a1a2aafe.mp3\", \"/storage/v1/object/public/pronunciation/v2/cynical-lt396-a1a2aafe.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/cynical-lt498-a1a2aafe.mp3\", \"/storage/v1/object/public/pronunciation/v2/cynical-lt132-a1a2aafe.mp3\", \"/storage/v1/object/public/pronunciation/v2/cynical-lt288-a1a2aafe.mp3\", \"/storage/v1/object/public/pronunciation/v2/cynical-lt42-a1a2aafe.mp3\", \"/storage/v1/object/public/pronunciation/v2/cynical-lt90-a1a2aafe.mp3\"]}}', 'Người hoài nghi thường không tin vào lòng tốt của người khác.', 'office', 1, 0),
('6b078fb8-314d-5be9-ae06-a1e2eac2e5bc', '0a4ec2d7-01c5-5457-a414-6530a08abf22', '04d0f65f-27b6-5a5f-bebd-c21a6e729b10', '5cfe7e21-e9bf-519c-a99f-264aa1c3d369', 'genome', '/ˈdʒiːnəʊm/', 'C1', 'noun', 'Toàn bộ vật liệu di truyền của một sinh vật.', 'the complete set of genetic information found in all cells of a living thing.', 'Scientists are working to map the entire human genome to understand genetic diseases.', 'Các nhà khoa học đang nỗ lực lập bản đồ toàn bộ bộ gen người để hiểu về các bệnh di truyền.', '{\"en\": \"The biotech firm announced a breakthrough in sequencing the genome of rare plant species.\", \"vi\": \"Công ty công nghệ sinh học thông báo đột phá trong việc giải mã bộ gen của các loài thực vật quý hiếm.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/genome-ljspeech-a5c9b737.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/genome-cori-a5c9b737.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/genome-0e6690b5.webp', NULL, NULL, '[{\"phrase\": \"human genome\", \"meaning\": \"bộ gen người\"}, {\"phrase\": \"genome sequencing\", \"meaning\": \"giải trình tự bộ gen\"}, {\"phrase\": \"genome mapping\", \"meaning\": \"lập bản đồ bộ gen\"}]', '[{\"word\": \"gene\", \"note_vi\": \"gene là một đoạn DNA, còn genome là toàn bộ vật liệu di truyền của sinh vật\"}]', '[{\"pos\": \"adjective\", \"word\": \"genomic\"}, {\"pos\": \"noun\", \"word\": \"genomics\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/genome-cori-a5c9b737.mp3\", \"/storage/v1/object/public/pronunciation/v2/genome-aru0-a5c9b737.mp3\", \"/storage/v1/object/public/pronunciation/v2/genome-aru5-a5c9b737.mp3\", \"/storage/v1/object/public/pronunciation/v2/genome-aru6-a5c9b737.mp3\", \"/storage/v1/object/public/pronunciation/v2/genome-aru10-a5c9b737.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/genome-aru9-a5c9b737.mp3\", \"/storage/v1/object/public/pronunciation/v2/genome-aru3-a5c9b737.mp3\", \"/storage/v1/object/public/pronunciation/v2/genome-aru7-a5c9b737.mp3\", \"/storage/v1/object/public/pronunciation/v2/genome-aru8-a5c9b737.mp3\", \"/storage/v1/object/public/pronunciation/v2/genome-aru2-a5c9b737.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/genome-ljspeech-a5c9b737.mp3\", \"/storage/v1/object/public/pronunciation/v2/genome-lt408-a5c9b737.mp3\", \"/storage/v1/object/public/pronunciation/v2/genome-lt138-a5c9b737.mp3\", \"/storage/v1/object/public/pronunciation/v2/genome-lt624-a5c9b737.mp3\", \"/storage/v1/object/public/pronunciation/v2/genome-lt396-a5c9b737.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/genome-lt498-a5c9b737.mp3\", \"/storage/v1/object/public/pronunciation/v2/genome-lt132-a5c9b737.mp3\", \"/storage/v1/object/public/pronunciation/v2/genome-lt288-a5c9b737.mp3\", \"/storage/v1/object/public/pronunciation/v2/genome-lt42-a5c9b737.mp3\", \"/storage/v1/object/public/pronunciation/v2/genome-lt90-a5c9b737.mp3\"]}}', 'Genome (bộ gen) là toàn bộ, còn gene (gen) chỉ là một phần nhỏ — đừng nhầm hai từ này.', 'technology', 1, 1),
('4b029eea-dfe8-5912-b1cc-2ca667282120', '0a4ec2d7-01c5-5457-a414-6530a08abf22', '04d0f65f-27b6-5a5f-bebd-c21a6e729b10', '5cfe7e21-e9bf-519c-a99f-264aa1c3d369', 'telomere', '/ˈtɛləmɪə/', 'C2', 'noun', 'Phần đầu mút của nhiễm sắc thể, bảo vệ DNA khỏi hư hại.', 'a protective structure at the end of a chromosome that prevents genetic material from degrading.', 'Scientists are studying how telomere length affects aging and disease.', 'Các nhà khoa học đang nghiên cứu cách độ dài telomere ảnh hưởng đến lão hóa và bệnh tật.', '{\"en\": \"The biotech firm is researching how telomere maintenance can improve the health of aging employees.\", \"vi\": \"Công ty công nghệ sinh học đang nghiên cứu cách duy trì telomere có thể cải thiện sức khỏe cho nhân viên lớn tuổi.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/telomere-ljspeech-00b1c8f7.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/telomere-cori-00b1c8f7.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/telomere-c1a3865b.webp', NULL, NULL, '[{\"phrase\": \"telomere length\", \"meaning\": \"độ dài telomere\"}, {\"phrase\": \"telomere shortening\", \"meaning\": \"sự rút ngắn telomere\"}]', NULL, NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/telomere-cori-00b1c8f7.mp3\", \"/storage/v1/object/public/pronunciation/v2/telomere-aru0-00b1c8f7.mp3\", \"/storage/v1/object/public/pronunciation/v2/telomere-aru5-00b1c8f7.mp3\", \"/storage/v1/object/public/pronunciation/v2/telomere-aru6-00b1c8f7.mp3\", \"/storage/v1/object/public/pronunciation/v2/telomere-aru10-00b1c8f7.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/telomere-aru9-00b1c8f7.mp3\", \"/storage/v1/object/public/pronunciation/v2/telomere-aru3-00b1c8f7.mp3\", \"/storage/v1/object/public/pronunciation/v2/telomere-aru7-00b1c8f7.mp3\", \"/storage/v1/object/public/pronunciation/v2/telomere-aru8-00b1c8f7.mp3\", \"/storage/v1/object/public/pronunciation/v2/telomere-aru2-00b1c8f7.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/telomere-ljspeech-00b1c8f7.mp3\", \"/storage/v1/object/public/pronunciation/v2/telomere-lt408-00b1c8f7.mp3\", \"/storage/v1/object/public/pronunciation/v2/telomere-lt138-00b1c8f7.mp3\", \"/storage/v1/object/public/pronunciation/v2/telomere-lt624-00b1c8f7.mp3\", \"/storage/v1/object/public/pronunciation/v2/telomere-lt396-00b1c8f7.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/telomere-lt498-00b1c8f7.mp3\", \"/storage/v1/object/public/pronunciation/v2/telomere-lt132-00b1c8f7.mp3\", \"/storage/v1/object/public/pronunciation/v2/telomere-lt288-00b1c8f7.mp3\", \"/storage/v1/object/public/pronunciation/v2/telomere-lt42-00b1c8f7.mp3\", \"/storage/v1/object/public/pronunciation/v2/telomere-lt90-00b1c8f7.mp3\"]}}', 'Thuật ngữ chuyên ngành sinh học, thường xuất hiện trong các bài đọc về y tế.', 'health', 1, 2),
('b9b714be-4bbb-587a-a9da-24b2a5aa3321', '0a4ec2d7-01c5-5457-a414-6530a08abf22', '04d0f65f-27b6-5a5f-bebd-c21a6e729b10', '5cfe7e21-e9bf-519c-a99f-264aa1c3d369', 'curvature', '/ˈkɜːvətʃə(r)/', 'C2', 'noun', 'Độ cong của một đường hoặc bề mặt.', 'the state of being bent or curved, or the degree to which something bends.', 'The architect carefully designed the gentle curvature of the bridge to blend with the landscape.', 'Kiến trúc sư đã cẩn thận thiết kế độ cong nhẹ nhàng của cây cầu để hòa hợp với cảnh quan.', '{\"en\": \"The unique curvature of the office building allows maximum natural light to enter the rooms.\", \"vi\": \"Độ cong độc đáo của tòa nhà văn phòng cho phép ánh sáng tự nhiên tối đa đi vào các phòng.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/curvature-ljspeech-e601ddc1.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/curvature-cori-e601ddc1.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/curvature-0b1ca71c.webp', '[\"bend\", \"curve\", \"arc\"]', '[\"straightness\"]', '[{\"phrase\": \"curvature of the earth\", \"meaning\": \"độ cong của trái đất\"}, {\"phrase\": \"spinal curvature\", \"meaning\": \"độ cong của cột sống\"}]', '[{\"word\": \"curve\", \"note_vi\": \"đường cong (danh từ chung), curvature là độ cong vật lý\"}]', '[{\"pos\": \"noun\", \"word\": \"curve\"}, {\"pos\": \"adjective\", \"word\": \"curved\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/curvature-cori-e601ddc1.mp3\", \"/storage/v1/object/public/pronunciation/v2/curvature-aru0-e601ddc1.mp3\", \"/storage/v1/object/public/pronunciation/v2/curvature-aru5-e601ddc1.mp3\", \"/storage/v1/object/public/pronunciation/v2/curvature-aru6-e601ddc1.mp3\", \"/storage/v1/object/public/pronunciation/v2/curvature-aru10-e601ddc1.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/curvature-aru9-e601ddc1.mp3\", \"/storage/v1/object/public/pronunciation/v2/curvature-aru3-e601ddc1.mp3\", \"/storage/v1/object/public/pronunciation/v2/curvature-aru7-e601ddc1.mp3\", \"/storage/v1/object/public/pronunciation/v2/curvature-aru8-e601ddc1.mp3\", \"/storage/v1/object/public/pronunciation/v2/curvature-aru2-e601ddc1.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/curvature-ljspeech-e601ddc1.mp3\", \"/storage/v1/object/public/pronunciation/v2/curvature-lt408-e601ddc1.mp3\", \"/storage/v1/object/public/pronunciation/v2/curvature-lt138-e601ddc1.mp3\", \"/storage/v1/object/public/pronunciation/v2/curvature-lt624-e601ddc1.mp3\", \"/storage/v1/object/public/pronunciation/v2/curvature-lt396-e601ddc1.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/curvature-lt498-e601ddc1.mp3\", \"/storage/v1/object/public/pronunciation/v2/curvature-lt132-e601ddc1.mp3\", \"/storage/v1/object/public/pronunciation/v2/curvature-lt288-e601ddc1.mp3\", \"/storage/v1/object/public/pronunciation/v2/curvature-lt42-e601ddc1.mp3\", \"/storage/v1/object/public/pronunciation/v2/curvature-lt90-e601ddc1.mp3\"]}}', 'Từ này thường dùng trong thiết kế, kiến trúc hoặc y học để chỉ mức độ cong.', 'manufacturing', 1, 3),
('61f2f4ce-4d90-58b3-a075-731acf2ca452', '0a4ec2d7-01c5-5457-a414-6530a08abf22', '04d0f65f-27b6-5a5f-bebd-c21a6e729b10', '5cfe7e21-e9bf-519c-a99f-264aa1c3d369', 'debugger', '/ˌdiːˈbʌɡə(r)/', 'B2', 'noun', 'Chương trình máy tính giúp tìm và sửa lỗi trong mã.', 'a software tool that helps programmers find and fix errors in computer code.', 'A good debugger is essential for software developers to identify and fix programming errors.', 'Một trình gỡ lỗi tốt là công cụ thiết yếu cho các nhà phát triển phần mềm để xác định và sửa lỗi lập trình.', '{\"en\": \"The IT team used a debugger to locate the error causing the billing software to crash.\", \"vi\": \"Nhóm IT đã dùng trình gỡ lỗi để tìm ra lỗi khiến phần mềm thanh toán bị sập.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/debugger-ljspeech-5fbd0224.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/debugger-cori-5fbd0224.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/debugger-844c8e82.webp', '[\"diagnostic tool\", \"error checker\"]', NULL, '[{\"phrase\": \"run a debugger\", \"meaning\": \"chạy trình gỡ lỗi\"}, {\"phrase\": \"built-in debugger\", \"meaning\": \"trình gỡ lỗi tích hợp sẵn\"}, {\"phrase\": \"debugger tool\", \"meaning\": \"công cụ gỡ lỗi\"}]', '[{\"word\": \"bug\", \"note_vi\": \"bug là lỗi trong code; debugger là công cụ dùng để tìm và sửa bug\"}]', '[{\"pos\": \"verb\", \"word\": \"debug\"}, {\"pos\": \"noun\", \"word\": \"debugging\"}, {\"pos\": \"noun\", \"word\": \"bug\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/debugger-cori-5fbd0224.mp3\", \"/storage/v1/object/public/pronunciation/v2/debugger-aru0-5fbd0224.mp3\", \"/storage/v1/object/public/pronunciation/v2/debugger-aru5-5fbd0224.mp3\", \"/storage/v1/object/public/pronunciation/v2/debugger-aru6-5fbd0224.mp3\", \"/storage/v1/object/public/pronunciation/v2/debugger-aru10-5fbd0224.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/debugger-aru9-5fbd0224.mp3\", \"/storage/v1/object/public/pronunciation/v2/debugger-aru3-5fbd0224.mp3\", \"/storage/v1/object/public/pronunciation/v2/debugger-aru7-5fbd0224.mp3\", \"/storage/v1/object/public/pronunciation/v2/debugger-aru8-5fbd0224.mp3\", \"/storage/v1/object/public/pronunciation/v2/debugger-aru2-5fbd0224.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/debugger-ljspeech-5fbd0224.mp3\", \"/storage/v1/object/public/pronunciation/v2/debugger-lt408-5fbd0224.mp3\", \"/storage/v1/object/public/pronunciation/v2/debugger-lt138-5fbd0224.mp3\", \"/storage/v1/object/public/pronunciation/v2/debugger-lt624-5fbd0224.mp3\", \"/storage/v1/object/public/pronunciation/v2/debugger-lt396-5fbd0224.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/debugger-lt498-5fbd0224.mp3\", \"/storage/v1/object/public/pronunciation/v2/debugger-lt132-5fbd0224.mp3\", \"/storage/v1/object/public/pronunciation/v2/debugger-lt288-5fbd0224.mp3\", \"/storage/v1/object/public/pronunciation/v2/debugger-lt42-5fbd0224.mp3\", \"/storage/v1/object/public/pronunciation/v2/debugger-lt90-5fbd0224.mp3\"]}}', 'Debugger xuất phát từ \'debug\' (gỡ lỗi); \'bug\' trong lập trình nghĩa là lỗi phần mềm.', 'technology', 1, 4),
('7d4294d1-a0e8-5d07-b8bf-f35c2d71a3a9', '0a4ec2d7-01c5-5457-a414-6530a08abf22', '04d0f65f-27b6-5a5f-bebd-c21a6e729b10', '5cfe7e21-e9bf-519c-a99f-264aa1c3d369', 'licensure', 'UK: /ˈlaɪsənʃə/ | US: /ˈlaɪsənʃər/', 'C1', 'noun', 'sự cấp phép, giấy phép hành nghề', 'the official granting of a permit or authority to perform professional activities legally.', 'Medical licensure is required for all practicing doctors.', 'Giấy phép hành nghề y tế là bắt buộc đối với tất cả các bác sĩ hành nghề.', '{\"en\": \"Engineers must meet strict education requirements to obtain professional licensure.\", \"vi\": \"Các kỹ sư phải đáp ứng các yêu cầu giáo dục nghiêm ngặt để có được sự cấp phép hành nghề chuyên môn.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/licensure-ljspeech-eecb4d74.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/licensure-cori-eecb4d74.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/licensure-96ba0e2e.webp', '[\"accreditation\", \"certification\", \"licensing\", \"authorization\"]', NULL, '[{\"phrase\": \"professional licensure\", \"meaning\": \"sự cấp phép hành nghề chuyên môn\"}, {\"phrase\": \"obtain licensure\", \"meaning\": \"đạt được sự cấp phép hành nghề\"}]', '[{\"word\": \"license\", \"note_vi\": \"license là bằng/giấy phép cụ thể, licensure là tư cách/sự cấp phép hành nghề\"}]', '[{\"pos\": \"noun\", \"word\": \"license\"}, {\"pos\": \"verb\", \"word\": \"license\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/licensure-cori-eecb4d74.mp3\", \"/storage/v1/object/public/pronunciation/v2/licensure-aru0-eecb4d74.mp3\", \"/storage/v1/object/public/pronunciation/v2/licensure-aru5-eecb4d74.mp3\", \"/storage/v1/object/public/pronunciation/v2/licensure-aru6-eecb4d74.mp3\", \"/storage/v1/object/public/pronunciation/v2/licensure-aru10-eecb4d74.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/licensure-aru9-eecb4d74.mp3\", \"/storage/v1/object/public/pronunciation/v2/licensure-