('f9d3d74b-f6fe-5a58-94d0-8047f900969f', '0a4ec2d7-01c5-5457-a414-6530a08abf22', '47a178f5-4e2b-53ff-ba27-3115edc232f3', 'dd9a43da-8a11-530e-9c0d-efa9c56d377b', 'savannah', '/səˈvænə/', 'B1', 'noun', 'Đồng cỏ rộng lớn ở vùng nhiệt đới hoặc cận nhiệt đới, có cây cối thưa thớt.', 'a large flat grassland with few trees in warm regions.', 'Tourists took photos of wild elephants migrating across the dry tropical savannah.', 'Du khách đã chụp ảnh những con voi hoang dã di cư qua thảo nguyên nhiệt đới khô hạn.', '{\"en\": \"The travel agency offered a safari tour across the Kenyan savannah.\", \"vi\": \"Công ty du lịch cung cấp tour ngắm cảnh hoang dã qua thảo nguyên Kenya.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/savannah-ljspeech-5a419452.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/savannah-cori-5a419452.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/savannah-329251cd.webp', '[\"grassland\", \"plain\"]', NULL, '[{\"phrase\": \"African savannah\", \"meaning\": \"thảo nguyên châu Phi\"}, {\"phrase\": \"savannah biome\", \"meaning\": \"quần xã thảo nguyên\"}, {\"phrase\": \"savannah region\", \"meaning\": \"vùng thảo nguyên\"}]', '[{\"word\": \"Savannah\", \"note_vi\": \"savannah là thảo nguyên, Savannah là tên thành phố Mỹ, viết hoa\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/savannah-cori-5a419452.mp3\", \"/storage/v1/object/public/pronunciation/v2/savannah-aru0-5a419452.mp3\", \"/storage/v1/object/public/pronunciation/v2/savannah-aru5-5a419452.mp3\", \"/storage/v1/object/public/pronunciation/v2/savannah-aru6-5a419452.mp3\", \"/storage/v1/object/public/pronunciation/v2/savannah-aru10-5a419452.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/savannah-aru9-5a419452.mp3\", \"/storage/v1/object/public/pronunciation/v2/savannah-aru3-5a419452.mp3\", \"/storage/v1/object/public/pronunciation/v2/savannah-aru7-5a419452.mp3\", \"/storage/v1/object/public/pronunciation/v2/sa