('c43fd35c-e039-5c92-a8e7-14509937d8f5', '0a4ec2d7-01c5-5457-a414-6530a08abf22', 'c478b78a-bddb-53f8-93a1-593aeddec3c8', '49971f7f-279a-572a-9b52-d26ca667e59b', 'courseware', '/ˈkɔːsweə(r)/', 'B2', 'noun', 'Phần mềm máy tính được thiết kế để hỗ trợ việc học hoặc giảng dạy.', 'computer software made to help teaching or learning activities.', 'The online platform provides interactive courseware for learning new languages.', 'Nền tảng trực tuyến cung cấp phần mềm học tập tương tác để học ngôn ngữ mới.', '{\"en\": \"Our hr department bought courseware to train new staff on safety.\", \"vi\": \"Phòng nhân sự của chúng tôi đã mua phần mềm học tập để đào tạo an toàn cho nhân viên mới.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/courseware-ljspeech-2089a699.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/courseware-cori-2089a699.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/courseware-6ee9a25c.webp', '[\"educational software\", \"training software\"]', NULL, '[{\"phrase\": \"interactive courseware\", \"meaning\": \"phần mềm học tương tác\"}, {\"phrase\": \"develop courseware\", \"meaning\": \"phát triển phần mềm giảng dạy\"}]', '[{\"word\": \"coursebook\", \"note_vi\": \"courseware là phần mềm, coursebook là sách giáo trình in.\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/courseware-cori-2089a699.mp3\", \"/storage/v1/object/public/pronunciation/v2/courseware-aru0-2089a699.mp3\", \"/storage/v1/object/public/pronunciation/v2/courseware-aru5-2089a699.mp3\", \"/storage/v1/object/public/pronunciation/v2/courseware-aru6-2089a699.mp3\", \"/storage/v1/object/public/pronunciation/v2/courseware-aru10-2089a699.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/courseware-aru9-2089a699.mp3\", \"/storage/v1/object/public/pronunciation/v2/courseware-aru3-2089a699.mp3\", \"/storage/v1/object/public/pronunciation/v2/courseware-aru7-2089a699.mp3\", \"/storage/v1/object/public/pronunciation/v