('f27978c9-bdba-5a77-a569-dfb228dd3a96', '0a4ec2d7-01c5-5457-a414-6530a08abf22', 'd7f3f4d3-b8fd-55db-8531-6d8fe51e20be', 'd57476b2-b93a-5aa1-8470-4b9c48ac5f56', 'chomp', '/tʃɒmp/', 'C1', 'verb', 'Nhai mạnh và ồn ào.', 'to chew food in a noisy way or to bite something repeatedly.', 'The hungry dog happily began to chomp on the big bone.', 'Con chó đói bụng vui vẻ bắt đầu nhai ngấu nghiến chiếc xương lớn.', '{\"en\": \"The office dog likes to chomp on its favorite rubber toy during lunch breaks.\", \"vi\": \"Chú chó của văn phòng thích nhai ngấu nghiến món đồ chơi cao su yêu thích trong giờ nghỉ trưa.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/chomp-ljspeech-6775b573.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/chomp-cori-6775b573.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/chomp-356dcfb5.webp', '[\"chew\", \"munch\"]', NULL, '[{\"phrase\": \"chomp on\", \"meaning\": \"nhai ngấu nghiến\"}, {\"phrase\": \"chomp away\", \"meaning\": \"tiếp tục nhai\"}]', '[{\"word\": \"champ\", \"note_vi\": \"Champ cũng có nghĩa là nhai, nhưng thường dùng trong cụm \'champ at the bit\'.\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/chomp-cori-6775b573.mp3\", \"/storage/v1/object/public/pronunciation/v2/chomp-aru0-6775b573.mp3\", \"/storage/v1/object/public/pronunciation/v2/chomp-aru5-6775b573.mp3\", \"/storage/v1/object/public/pronunciation/v2/chomp-aru6-6775b573.mp3\", \"/storage/v1/object/public/pronunciation/v2/chomp-aru10-6775b573.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/chomp-aru9-6775b573.mp3\", \"/storage/v1/object/public/pronunciation/v2/chomp-aru3-6775b573.mp3\", \"/storage/v1/object/public/pronunciation/v2/chomp-aru7-6775b573.mp3\", \"/storage/v1/object/public/pronunciation/v2/chomp-aru8-6775b573.mp3\", \"/storage/v1/object/public/pronunciation/v2/chomp-aru2-6775b573.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/chomp-ljspeech-6775b573.m