('04b22469-69bb-591e-b340-a163af3b42ab', '0a4ec2d7-01c5-5457-a414-6530a08abf22', 'f25f3758-a70d-5454-b39a-985261b04987', 'fbdb8355-d325-5e3e-a9eb-00bb7f97d2b3', 'spoilage', 'UK: /ˈspɔɪlɪdʒ/ | US: /ˈspɔɪlɪdʒ/', 'C1', 'noun', 'sự hư hỏng', 'The process of food or organic matter decaying and becoming unfit for consumption.', 'The food was thrown away due to spoilage.', 'Thức ăn bị vứt bỏ do hư hỏng.', '{\"en\": \"Proper refrigeration management reduced food spoilage at the hotel\'s main restaurant.\", \"vi\": \"Quản lý bảo quản lạnh đúng cách đã giảm thiểu sự hư hỏng thực phẩm tại nhà hàng chính của khách sạn.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/spoilage-ljspeech-23e54c4d.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/spoilage-cori-23e54c4d.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/spoilage-632ec3d7.webp', '[\"decay\", \"decomposition\", \"deterioration\", \"rot\"]', '[\"preservation\", \"conservation\"]', '[{\"phrase\": \"food spoilage\", \"meaning\": \"sự hư hỏng thực phẩm\"}, {\"phrase\": \"prevent spoilage\", \"meaning\": \"ngăn ngừa sự hư hỏng\"}]', '[{\"word\": \"damage\", \"note_vi\": \"Hư hại vật lý/thiệt hại đồ đạc thiết bị, còn spoilage hay dùng cho hàng thực phẩm/nông sản.\"}]', '[{\"pos\": \"verb\", \"word\": \"spoil\"}, {\"pos\": \"adjective\", \"word\": \"spoiled\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/spoilage-cori-23e54c4d.mp3\", \"/storage/v1/object/public/pronunciation/v2/spoilage-aru0-23e54c4d.mp3\", \"/storage/v1/object/public/pronunciation/v2/spoilage-aru5-23e54c4d.mp3\", \"/storage/v1/object/public/pronunciation/v2/spoilage-aru6-23e54c4d.mp3\", \"/storage/v1/object/public/pronunciation/v2/spoilage-aru10-23e54c4d.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/spoilage-aru9-23e54c4d.mp3\", \"/storage/v1/object/public/pronunciation/v2/spoilage-aru3-23e54c4d.mp3\", \"/storage/v1/object/public/pronunciation/v2/spoilage-aru7-23e54c4d.mp3\