('eecee0ac-99a6-5d0e-92cf-1636446f8995', '0a4ec2d7-01c5-5457-a414-6530a08abf22', 'f4cc0387-36ec-5479-a8c0-8d7a26b6279b', 'afacdeac-0803-5fad-a946-c49d166b4644', 'socket', '/ˈsɒkɪt/', 'A2', 'noun', 'Ổ cắm điện trên tường hoặc một lỗ để lắp thứ gì vào.', 'a place on a wall where you can connect electrical equipment to the power supply.', 'Make sure the plug is fully inserted into the wall socket.', 'Hãy đảm bảo phích cắm được cắm hoàn toàn vào ổ điện trên tường.', '{\"en\": \"Please ensure the office printer is connected to a grounded wall socket for safety.\", \"vi\": \"Vui lòng đảm bảo máy in văn phòng được kết nối với ổ cắm điện có tiếp đất để an toàn.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/socket-ljspeech-897d2105.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/socket-cori-897d2105.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/socket-6acb8014.webp', '[\"outlet\", \"power point\"]', NULL, '[{\"phrase\": \"wall socket\", \"meaning\": \"ổ cắm trên tường\"}, {\"phrase\": \"plug into\", \"meaning\": \"cắm vào\"}]', '[{\"word\": \"plug\", \"note_vi\": \"Plug là phích cắm, socket là ổ cắm.\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/socket-cori-897d2105.mp3\", \"/storage/v1/object/public/pronunciation/v2/socket-aru0-897d2105.mp3\", \"/storage/v1/object/public/pronunciation/v2/socket-aru5-897d2105.mp3\", \"/storage/v1/object/public/pronunciation/v2/socket-aru6-897d2105.mp3\", \"/storage/v1/object/public/pronunciation/v2/socket-aru10-897d2105.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/socket-aru9-897d2105.mp3\", \"/storage/v1/object/public/pronunciation/v2/socket-aru3-897d2105.mp3\", \"/storage/v1/object/public/pronunciation/v2/socket-aru7-897d2105.mp3\", \"/storage/v1/object/public/pronunciation/v2/socket-aru8-897d2105.mp3\", \"/storage/v1/object/public/pronunciation/v2/socket-aru2-897d2105.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/