('a4a8aab8-a7fd-59b6-be8b-545d70217b09', '51593eab-afc9-5ad7-9776-2e5deeada393', '05426358-6357-5bc3-8ffe-0d4d08c49ff3', '8ccc73d2-6d2f-5b8a-8169-ade3bbec449b', 'appliance', 'UK: /əˈplaɪəns/ | US: /əˈplaɪəns/', 'B2', 'noun', 'thiết bị, dụng cụ (thường dùng trong nhà bếp hoặc gia đình)', 'A piece of electrical equipment designed to perform a specific household task.', 'The store sells a variety of kitchen appliances.', 'Cửa hàng bán nhiều loại thiết bị nhà bếp.', '{\"en\": \"The store is offering discounts on energy-efficient home appliances this month.\", \"vi\": \"Cửa hàng đang giảm giá cho các thiết bị gia dụng tiết kiệm năng lượng trong tháng này.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/appliance-ljspeech-67c65757.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/appliance-cori-67c65757.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/appliance-0e6b0244.webp', '[\"device\", \"gadget\", \"equipment\"]', NULL, '[{\"phrase\": \"household appliance\", \"meaning\": \"thiết bị gia dụng\"}, {\"phrase\": \"kitchen appliance\", \"meaning\": \"dụng cụ làm bếp\"}]', '[{\"word\": \"application\", \"note_vi\": \"Application là đơn đăng ký hoặc phần mềm ứng dụng, không phải đồ gia dụng.\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/appliance-cori-67c65757.mp3\", \"/storage/v1/object/public/pronunciation/v2/appliance-aru0-67c65757.mp3\", \"/storage/v1/object/public/pronunciation/v2/appliance-aru5-67c65757.mp3\", \"/storage/v1/object/public/pronunciation/v2/appliance-aru6-67c65757.mp3\", \"/storage/v1/object/public/pronunciation/v2/appliance-aru10-67c65757.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/appliance-aru9-67c65757.mp3\", \"/storage/v1/object/public/pronunciation/v2/appliance-aru3-67c65757.mp3\", \"/storage/v1/object/public/pronunciation/v2/appliance-aru7-67c65757.mp3\", \"/storage/v1/object/public/pronunciation/v2/appliance-aru8-67c65757.mp3\", \"/storage/v1/object/