('cd5aa75a-ca9d-559a-913a-e316736350a4', '51593eab-afc9-5ad7-9776-2e5deeada393', '05426358-6357-5bc3-8ffe-0d4d08c49ff3', '8ccc73d2-6d2f-5b8a-8169-ade3bbec449b', 'alarm', 'UK: /əˈlɑːm/ | US: /əˈlɑːrm/', 'B1', 'noun', 'chuông báo động', 'a device that makes a loud sound to warn people of immediate danger or emergency.', 'The fire alarm sounded during the drill.', 'Chuông báo cháy vang lên trong buổi diễn tập.', '{\"en\": \"All employees must evacuate the building immediately when the fire alarm sounds.\", \"vi\": \"Tất cả nhân viên phải sơ tán khỏi tòa nhà ngay lập tức khi chuông báo cháy vang lên.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/alarm-ljspeech-73468898.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/alarm-cori-73468898.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/alarm-a971a2b3.webp', '[\"siren\", \"warning signal\", \"alert\"]', NULL, '[{\"phrase\": \"fire alarm\", \"meaning\": \"chuông báo cháy\"}, {\"phrase\": \"security alarm\", \"meaning\": \"báo động an ninh\"}, {\"phrase\": \"sound the alarm\", \"meaning\": \"kích hoạt chuông báo động\"}]', '[{\"word\": \"alert\", \"note_vi\": \"alert là thông tin/cảnh báo, còn alarm thường là thiết bị hoặc âm thanh báo động\"}]', '[{\"pos\": \"verb\", \"word\": \"alarm\"}, {\"pos\": \"adjective\", \"word\": \"alarming\"}, {\"pos\": \"adverb\", \"word\": \"alarmingly\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/alarm-cori-73468898.mp3\", \"/storage/v1/object/public/pronunciation/v2/alarm-aru0-73468898.mp3\", \"/storage/v1/object/public/pronunciation/v2/alarm-aru5-73468898.mp3\", \"/storage/v1/object/public/pronunciation/v2/alarm-aru6-73468898.mp3\", \"/storage/v1/object/public/pronunciation/v2/alarm-aru10-73468898.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/alarm-aru9-73468898.mp3\", \"/storage/v1/object/public/pronunciation/v2/alarm-aru3-73468898.mp3\", \"/storage/v1/object/public/pronunciation/v2/alarm-aru7-7346