('4179741e-30b0-5337-a6c4-ccaf19094480', '51593eab-afc9-5ad7-9776-2e5deeada393', '05426358-6357-5bc3-8ffe-0d4d08c49ff3', '8ccc73d2-6d2f-5b8a-8169-ade3bbec449b', 'grumble', '/ˈɡrʌmbl/', 'B1', 'verb', 'Phàn nàn hoặc càu nhàu một cách khó chịu.', 'to complain or speak in a low, discontented voice.', 'He often grumbles about the long working hours.', 'Anh ấy thường càu nhàu về những giờ làm việc dài.', '{\"en\": \"Employees grumble when the office temperature is set too cold in winter.\", \"vi\": \"Nhân viên càu nhàu khi nhiệt độ văn phòng được đặt quá lạnh vào mùa đông.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/grumble-ljspeech-3491a2d2.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/grumble-cori-3491a2d2.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/grumble-e6577dd9.webp', '[\"complain\", \"moan\"]', '[\"praise\"]', '[{\"phrase\": \"grumble about\", \"meaning\": \"càu nhàu về\"}, {\"phrase\": \"grumble at\", \"meaning\": \"càu nhàu với\"}]', '[{\"word\": \"mumble\", \"note_vi\": \"mumble là nói không rõ, grumble là phàn nàn\"}]', '[{\"pos\": \"noun\", \"word\": \"grumbling\"}, {\"pos\": \"noun\", \"word\": \"grumbler\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/grumble-cori-3491a2d2.mp3\", \"/storage/v1/object/public/pronunciation/v2/grumble-aru0-3491a2d2.mp3\", \"/storage/v1/object/public/pronunciation/v2/grumble-aru5-3491a2d2.mp3\", \"/storage/v1/object/public/pronunciation/v2/grumble-aru6-3491a2d2.mp3\", \"/storage/v1/object/public/pronunciation/v2/grumble-aru10-3491a2d2.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/grumble-aru9-3491a2d2.mp3\", \"/storage/v1/object/public/pronunciation/v2/grumble-aru3-3491a2d2.mp3\", \"/storage/v1/object/public/pronunciation/v2/grumble-aru7-3491a2d2.mp3\", \"/storage/v1/object/public/pronunciation/v2/grumble-aru8-3491a2d2.mp3\", \"/storage/v1/object/public/pronunciation/v2/grumble-aru2-3491a2d2.mp3\"]}, \"us\": {\"nu\": [\"/storage