('7535be93-cb89-5751-a505-9a1b52f47068', '51593eab-afc9-5ad7-9776-2e5deeada393', '072fa9a4-7ee0-5422-bd51-0a6d4139b152', '9aba316e-feb9-5014-b111-2b0eff423d4a', 'buyer', 'UK: /ˈbaɪə/ | US: /ˈbaɪər/', 'B1', 'noun', 'người mua', 'a person or entity that purchases goods, property, or services for a financial cost', 'We are actively looking for a buyer for our old office building.', 'Chúng tôi đang tích cực tìm kiếm người mua cho tòa nhà văn phòng cũ của mình.', '{\"en\": \"The potential buyer requested a thorough property inspection before submitting a final offer.\", \"vi\": \"Người mua tiềm năng đã yêu cầu kiểm tra kỹ lưỡng bất động sản trước khi đưa ra lời đề nghị cuối cùng.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/buyer-ljspeech-9b165e49.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/buyer-cori-9b165e49.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/buyer-3e393c3c.webp', '[\"purchaser\", \"client\", \"customer\"]', '[\"seller\", \"vendor\"]', '[{\"phrase\": \"prospective buyer\", \"meaning\": \"người mua tiềm năng\"}, {\"phrase\": \"buyer\'s market\", \"meaning\": \"thị trường có lợi cho người mua\"}]', NULL, '[{\"pos\": \"verb\", \"word\": \"buy\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/buyer-cori-9b165e49.mp3\", \"/storage/v1/object/public/pronunciation/v2/buyer-aru0-9b165e49.mp3\", \"/storage/v1/object/public/pronunciation/v2/buyer-aru5-9b165e49.mp3\", \"/storage/v1/object/public/pronunciation/v2/buyer-aru6-9b165e49.mp3\", \"/storage/v1/object/public/pronunciation/v2/buyer-aru10-9b165e49.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/buyer-aru9-9b165e49.mp3\", \"/storage/v1/object/public/pronunciation/v2/buyer-aru3-9b165e49.mp3\", \"/storage/v1/object/public/pronunciation/v2/buyer-aru7-9b165e49.mp3\", \"/storage/v1/object/public/pronunciation/v2/buyer-aru8-9b165e49.mp3\", \"/storage/v1/object/public/pronunciation/v2/buyer-aru2-9b165e49.mp3\"]}, \"us\": {\"nu\