('84b45489-b85f-564d-8df5-ba35742c2d15', '51593eab-afc9-5ad7-9776-2e5deeada393', '072fa9a4-7ee0-5422-bd51-0a6d4139b152', '9aba316e-feb9-5014-b111-2b0eff423d4a', 'unfit', '/ʌnˈfɪt/', 'B1', 'adjective', 'Không phù hợp, không đủ tiêu chuẩn hoặc không khỏe mạnh.', 'not suitable for a purpose or not in good physical condition.', 'The old building was declared unfit for human habitation.', 'Tòa nhà cũ đã bị tuyên bố là không phù hợp để con người sinh sống.', '{\"en\": \"The candidate was found unfit for the supervisor role after the interview.\", \"vi\": \"Ứng viên được đánh giá không phù hợp cho vị trí giám sát sau cuộc phỏng vấn.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/unfit-ljspeech-e469f4fa.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/unfit-cori-e469f4fa.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/unfit-4022462d.webp', '[\"unsuitable\", \"unqualified\"]', '[\"fit\", \"suitable\"]', '[{\"phrase\": \"unfit for purpose\", \"meaning\": \"không phù hợp mục đích\"}, {\"phrase\": \"unfit for work\", \"meaning\": \"không đủ sức khỏe để làm việc\"}]', '[{\"word\": \"unfair\", \"note_vi\": \"unfair là không công bằng, unfit là không phù hợp\"}]', '[{\"pos\": \"noun\", \"word\": \"unfitness\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/unfit-cori-e469f4fa.mp3\", \"/storage/v1/object/public/pronunciation/v2/unfit-aru0-e469f4fa.mp3\", \"/storage/v1/object/public/pronunciation/v2/unfit-aru5-e469f4fa.mp3\", \"/storage/v1/object/public/pronunciation/v2/unfit-aru6-e469f4fa.mp3\", \"/storage/v1/object/public/pronunciation/v2/unfit-aru10-e469f4fa.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/unfit-aru9-e469f4fa.mp3\", \"/storage/v1/object/public/pronunciation/v2/unfit-aru3-e469f4fa.mp3\", \"/storage/v1/object/public/pronunciation/v2/unfit-aru7-e469f4fa.mp3\", \"/storage/v1/object/public/pronunciation/v2/unfit-aru8-e469f4fa.mp3\", \"/storage/v1/object/public/pronunciation/v2/unfit-