('2bffb280-7748-5a89-b79d-2d8fa7a3db73', '51593eab-afc9-5ad7-9776-2e5deeada393', '09519a5e-a6bc-5f84-84d6-079e5660aa0a', '5f88d697-e32b-5b62-bc23-3b1e78cf0155', 'notify', '/ˈnəʊtɪfaɪ/', 'B1', 'verb', 'chính thức báo tin, cho biết thông tin', 'to tell someone officially about something or give them important information about an event.', 'The airline will notify passengers promptly in case of any flight delays.', 'Hãng hàng không sẽ thông báo kịp thời cho hành khách trong trường hợp chuyến bay bị hoãn.', '{\"en\": \"Human resources will notify all successful candidates about their interview schedules by tomorrow morning.\", \"vi\": \"Phòng nhân sự sẽ thông báo cho tất cả các ứng viên thành công về lịch phỏng vấn trước sáng mai.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/notify-ljspeech-4f08301d.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/notify-cori-4f08301d.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/notify-7a863551.webp', '[\"inform\", \"advise\", \"apprise\"]', NULL, '[{\"phrase\": \"notify somebody of something\", \"meaning\": \"thông báo cho ai về việc gì\"}, {\"phrase\": \"notify in advance\", \"meaning\": \"thông báo trước\"}]', '[{\"word\": \"notice\", \"note_vi\": \"Notify là động từ thông báo; Notice là nhận ra hoặc bảng thông báo.\"}]', '[{\"pos\": \"noun\", \"word\": \"notification\"}, {\"pos\": \"noun\", \"word\": \"notice\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/notify-cori-4f08301d.mp3\", \"/storage/v1/object/public/pronunciation/v2/notify-aru0-4f08301d.mp3\", \"/storage/v1/object/public/pronunciation/v2/notify-aru5-4f08301d.mp3\", \"/storage/v1/object/public/pronunciation/v2/notify-aru6-4f08301d.mp3\", \"/storage/v1/object/public/pronunciation/v2/notify-aru10-4f08301d.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/notify-aru9-4f08301d.mp3\", \"/storage/v1/object/public/pronunciation/v2/notify-aru3-4f08301d.mp3\", \"/storage/v1/object/public/pr