('b6a59cb6-5b42-51d1-b346-34706eee6399', '51593eab-afc9-5ad7-9776-2e5deeada393', '09519a5e-a6bc-5f84-84d6-079e5660aa0a', '5f88d697-e32b-5b62-bc23-3b1e78cf0155', 'basement', 'UK: /ˈbeɪsmənt/ | US: /ˈbeɪsmənt/', 'B1', 'noun', 'tầng hầm', 'a room or floor of a building that is partially or completely below ground level.', 'The old records are stored in the basement.', 'Các hồ sơ cũ được lưu trữ ở tầng hầm.', '{\"en\": \"Maintenance staff are currently inspecting the electrical panels located in the basement.\", \"vi\": \"Nhân viên bảo trì hiện đang kiểm tra các bảng điện nằm ở tầng hầm.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/basement-ljspeech-52f948f2.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/basement-cori-52f948f2.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/basement-228b2ee2.webp', '[\"cellar\", \"underground level\"]', '[\"attic\", \"roof\"]', '[{\"phrase\": \"basement parking\", \"meaning\": \"bãi đỗ xe tầng hầm\"}, {\"phrase\": \"basement storage\", \"meaning\": \"kho lưu trữ ở tầng hầm\"}]', '[{\"word\": \"cellar\", \"note_vi\": \"hầm chứa (thường dùng chứa rượu hoặc thực phẩm dưới lòng đất)\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/basement-cori-52f948f2.mp3\", \"/storage/v1/object/public/pronunciation/v2/basement-aru0-52f948f2.mp3\", \"/storage/v1/object/public/pronunciation/v2/basement-aru5-52f948f2.mp3\", \"/storage/v1/object/public/pronunciation/v2/basement-aru6-52f948f2.mp3\", \"/storage/v1/object/public/pronunciation/v2/basement-aru10-52f948f2.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/basement-aru9-52f948f2.mp3\", \"/storage/v1/object/public/pronunciation/v2/basement-aru3-52f948f2.mp3\", \"/storage/v1/object/public/pronunciation/v2/basement-aru7-52f948f2.mp3\", \"/storage/v1/object/public/pronunciation/v2/basement-aru8-52f948f2.mp3\", \"/storage/v1/object/public/pronunciation/v2/basement-aru2-52f948f2.mp3\"]}, \"us\": {\"nu\": [\"/st