('f32e3e46-6f14-5acd-9372-6b4b6829ef1c', '51593eab-afc9-5ad7-9776-2e5deeada393', '20992d35-b257-51b9-8359-24a389f1d897', '6b695fc4-d861-57d0-ab15-733677a6f057', 'waterfront', 'UK: /ˈwɔːtəfrʌnt/ | US: /ˈwɔtərfrʌnt/', 'B2', 'noun', 'bờ sông/biển', 'a section of land or area of a town that borders a body of water.', 'They enjoyed a stroll along the waterfront.', 'Họ thích đi dạo dọc bờ sông.', '{\"en\": \"The company decided to construct its new headquarters on the downtown waterfront.\", \"vi\": \"Công ty đã quyết định xây dựng trụ sở mới tại khu vực bờ sông trung tâm thành phố.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/waterfront-ljspeech-0328f247.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/waterfront-cori-0328f247.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/waterfront-598c4d84.webp', '[\"harborfront\", \"shoreline\", \"coastline\"]', NULL, '[{\"phrase\": \"waterfront property\", \"meaning\": \"bất động sản ven sông/biển\"}, {\"phrase\": \"waterfront restaurant\", \"meaning\": \"nhà hàng ven bờ sông/biển\"}]', NULL, NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/waterfront-cori-0328f247.mp3\", \"/storage/v1/object/public/pronunciation/v2/waterfront-aru0-0328f247.mp3\", \"/storage/v1/object/public/pronunciation/v2/waterfront-aru5-0328f247.mp3\", \"/storage/v1/object/public/pronunciation/v2/waterfront-aru6-0328f247.mp3\", \"/storage/v1/object/public/pronunciation/v2/waterfront-aru10-0328f247.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/waterfront-aru9-0328f247.mp3\", \"/storage/v1/object/public/pronunciation/v2/waterfront-aru3-0328f247.mp3\", \"/storage/v1/object/public/pronunciation/v2/waterfront-aru7-0328f247.mp3\", \"/storage/v1/object/public/pronunciation/v2/waterfront-aru8-0328f247.mp3\", \"/storage/v1/object/public/pronunciation/v2/waterfront-aru2-0328f247.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/waterfront-ljspeech-0328f247.mp