('7e1265bd-e876-59ff-8ac4-be5e3a05b49f', '51593eab-afc9-5ad7-9776-2e5deeada393', '20992d35-b257-51b9-8359-24a389f1d897', '6b695fc4-d861-57d0-ab15-733677a6f057', 'ambitious', 'UK: /æmˈbɪʃəs/ | US: /æmˈbɪʃəs/', 'B1', 'adjective', 'tham vọng', 'having a strong desire to achieve success, power, wealth, or high status.', 'She is an ambitious employee who aims for promotion.', 'Cô ấy là một nhân viên tham vọng, luôn hướng tới việc thăng chức.', '{\"en\": \"The company set an ambitious sales target for the upcoming fiscal year.\", \"vi\": \"Công ty đã đặt ra một mục tiêu doanh số đầy tham vọng cho năm tài chính sắp tới.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/ambitious-ljspeech-b8ed474e.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/ambitious-cori-b8ed474e.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/ambitious-edd90a1b.webp', '[\"aspiring\", \"determined\", \"driven\", \"motivated\"]', '[\"unambitious\", \"apathetic\", \"lazy\"]', '[{\"phrase\": \"ambitious goal\", \"meaning\": \"mục tiêu tham vọng\"}, {\"phrase\": \"ambitious plan\", \"meaning\": \"kế hoạch đầy tham vọng\"}]', NULL, '[{\"pos\": \"noun\", \"word\": \"ambition\"}, {\"pos\": \"adverb\", \"word\": \"ambitiously\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/ambitious-cori-b8ed474e.mp3\", \"/storage/v1/object/public/pronunciation/v2/ambitious-aru0-b8ed474e.mp3\", \"/storage/v1/object/public/pronunciation/v2/ambitious-aru5-b8ed474e.mp3\", \"/storage/v1/object/public/pronunciation/v2/ambitious-aru6-b8ed474e.mp3\", \"/storage/v1/object/public/pronunciation/v2/ambitious-aru10-b8ed474e.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/ambitious-aru9-b8ed474e.mp3\", \"/storage/v1/object/public/pronunciation/v2/ambitious-aru3-b8ed474e.mp3\", \"/storage/v1/object/public/pronunciation/v2/ambitious-aru7-b8ed474e.mp3\", \"/storage/v1/object/public/pronunciation/v2/ambitious-aru8-b8ed474e.mp3\", \"/storage/v1/object/public/