('7fc20022-f2d5-567f-8833-82c8f9bd55ff', '51593eab-afc9-5ad7-9776-2e5deeada393', '26ad1d8d-b0c4-5787-ab0a-ed1148635970', '66bafade-0076-5f11-8905-773ee6625ddf', 'authentic', 'UK: /ɔːˈθɛntɪk/ | US: /ɔˈθɛntɪk/', 'B2', 'adjective', 'đích thực, nguyên bản', 'genuine, original, and not copied or false in origin or overall character.', 'We bought an authentic antique clock at the market.', 'Chúng tôi đã mua một chiếc đồng hồ cổ đích thực ở chợ.', '{\"en\": \"The new restaurant is famous for serving authentic Italian cuisine using imported ingredients.\", \"vi\": \"Nhà hàng mới nổi tiếng với việc phục vụ ẩm thực Ý nguyên bản sử dụng nguyên liệu nhập khẩu.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/authentic-ljspeech-aa62cc26.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/authentic-cori-aa62cc26.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/authentic-798abb50.webp', '[\"genuine\", \"real\", \"legitimate\", \"original\"]', '[\"fake\", \"counterfeit\", \"inauthentic\"]', '[{\"phrase\": \"authentic document\", \"meaning\": \"văn bản/tài liệu xác thực\"}, {\"phrase\": \"authentic experience\", \"meaning\": \"trải nghiệm chân thực\"}]', NULL, '[{\"pos\": \"adverb\", \"word\": \"authentically\"}, {\"pos\": \"noun\", \"word\": \"authenticity\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/authentic-cori-aa62cc26.mp3\", \"/storage/v1/object/public/pronunciation/v2/authentic-aru0-aa62cc26.mp3\", \"/storage/v1/object/public/pronunciation/v2/authentic-aru5-aa62cc26.mp3\", \"/storage/v1/object/public/pronunciation/v2/authentic-aru6-aa62cc26.mp3\", \"/storage/v1/object/public/pronunciation/v2/authentic-aru10-aa62cc26.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/authentic-aru9-aa62cc26.mp3\", \"/storage/v1/object/public/pronunciation/v2/authentic-aru3-aa62cc26.mp3\", \"/storage/v1/object/public/pronunciation/v2/authentic-aru7-aa62cc26.mp3\", \"/storage/v1/object/public/pronunciation/v2/aut