('3bd146fb-ed7a-5963-a158-85577157268b', '51593eab-afc9-5ad7-9776-2e5deeada393', '28a9fba9-3bc8-5d68-a3a5-c5d488d18c97', '2d26b9d8-2dbf-5453-bbd2-59178d6ece60', 'clemency', '/ˈklemənsi/', 'C1', 'noun', 'sự khoan dung, nhân từ, thường là giảm nhẹ hình phạt.', 'the act of showing mercy by reducing a legal punishment.', 'The prisoner appealed to the governor for clemency.', 'Tù nhân đã kháng cáo lên thống đốc để xin khoan hồng.', '{\"en\": \"The governor\'s clemency reduced the convict\'s sentence after good behavior.\", \"vi\": \"Sự khoan dung của thống đốc đã giảm án cho tù nhân sau cư xử tốt.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/clemency-ljspeech-847c9a62.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/clemency-cori-847c9a62.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/clemency-e87a9763.webp', '[\"mercy\", \"leniency\"]', '[\"severity\"]', '[{\"phrase\": \"grant clemency\", \"meaning\": \"ban sự khoan dung\"}, {\"phrase\": \"appeal for clemency\", \"meaning\": \"kháng án xin khoan hồng\"}, {\"phrase\": \"show clemency\", \"meaning\": \"thể hiện lòng nhân từ\"}]', '[{\"word\": \"emergency\", \"note_vi\": \"emergency là tình trạng khẩn cấp, không liên quan\"}]', '[{\"pos\": \"adjective\", \"word\": \"clement\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/clemency-cori-847c9a62.mp3\", \"/storage/v1/object/public/pronunciation/v2/clemency-aru0-847c9a62.mp3\", \"/storage/v1/object/public/pronunciation/v2/clemency-aru5-847c9a62.mp3\", \"/storage/v1/object/public/pronunciation/v2/clemency-aru6-847c9a62.mp3\", \"/storage/v1/object/public/pronunciation/v2/clemency-aru10-847c9a62.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/clemency-aru9-847c9a62.mp3\", \"/storage/v1/object/public/pronunciation/v2/clemency-aru3-847c9a62.mp3\", \"/storage/v1/object/public/pronunciation/v2/clemency-aru7-847c9a62.mp3\", \"/storage/v1/object/public/pronunciation/v2/clemency-aru8-847c9a62.mp3