('2795d314-0edd-53b1-af64-02671026500d', '51593eab-afc9-5ad7-9776-2e5deeada393', '34497580-daaf-50cc-841c-a36a82e6aff6', '411ab854-dc1a-546a-a2da-009db62e92af', 'audience', 'UK: /ˈɔːdiəns/ | US: /ˈɔdiəns/', 'B1', 'noun', 'khán giả', 'a group of assembled listeners or viewers gathered to watch or listen to a performance.', 'The audience applauded loudly after the speech.', 'Khán giả vỗ tay nồng nhiệt sau bài phát biểu.', '{\"en\": \"The speaker kept the audience engaged throughout the entire two-hour presentation.\", \"vi\": \"Diễn giả đã giữ sự chú ý của khán giả xuyên suốt bài thuyết trình kéo dài hai giờ.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/audience-ljspeech-a4930bb8.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/audience-cori-a4930bb8.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/audience-7a6cc976.webp', '[\"listeners\", \"viewers\", \"spectators\", \"assembly\"]', NULL, '[{\"phrase\": \"target audience\", \"meaning\": \"khán giả/đối tượng mục tiêu\"}, {\"phrase\": \"audience reaction\", \"meaning\": \"phản ứng của khán giả\"}]', '[{\"word\": \"spectator\", \"note_vi\": \"spectator thường dùng để chỉ người xem các sự kiện thể thao ngoài trời\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/audience-cori-a4930bb8.mp3\", \"/storage/v1/object/public/pronunciation/v2/audience-aru0-a4930bb8.mp3\", \"/storage/v1/object/public/pronunciation/v2/audience-aru5-a4930bb8.mp3\", \"/storage/v1/object/public/pronunciation/v2/audience-aru6-a4930bb8.mp3\", \"/storage/v1/object/public/pronunciation/v2/audience-aru10-a4930bb8.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/audience-aru9-a4930bb8.mp3\", \"/storage/v1/object/public/pronunciation/v2/audience-aru3-a4930bb8.mp3\", \"/storage/v1/object/public/pronunciation/v2/audience-aru7-a4930bb8.mp3\", \"/storage/v1/object/public/pronunciation/v2/audience-aru8-a4930bb8.mp3\", \"/storage/v1/object/public/pronunciation/v2/audienc