('7b29b8f0-960a-5efa-980a-b15ed627f8f3', '51593eab-afc9-5ad7-9776-2e5deeada393', '3f00c09c-8fb8-5a5e-a16a-75a41dbd5327', 'be85c457-7679-5aa4-9f9b-7595dfd65a0c', 'fragrant', '/ˈfreɪɡrənt/', 'B2', 'adjective', 'Có mùi thơm dễ chịu.', 'having a pleasant, sweet, and nice smell.', 'The garden was filled with fragrant roses blooming in the sun.', 'Khu vườn tràn ngập những bông hồng thơm ngát nở dưới nắng.', '{\"en\": \"The hotel lobby was decorated with fragrant flowers to welcome the guests.\", \"vi\": \"Sảnh khách sạn được trang trí bằng những bông hoa thơm ngát để chào đón khách.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/fragrant-ljspeech-ced2ee26.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/fragrant-cori-ced2ee26.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/fragrant-fbb158ac.webp', '[\"scented\", \"aromatic\", \"perfumed\"]', '[\"smelly\", \"malodorous\"]', '[{\"phrase\": \"fragrant flowers\", \"meaning\": \"hoa thơm\"}, {\"phrase\": \"fragrant oil\", \"meaning\": \"dầu thơm\"}]', '[{\"word\": \"flagrant\", \"note_vi\": \"nghĩa là trắng trợn, rõ ràng (tội lỗi)\"}]', '[{\"pos\": \"noun\", \"word\": \"fragrance\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/fragrant-cori-ced2ee26.mp3\", \"/storage/v1/object/public/pronunciation/v2/fragrant-aru0-ced2ee26.mp3\", \"/storage/v1/object/public/pronunciation/v2/fragrant-aru5-ced2ee26.mp3\", \"/storage/v1/object/public/pronunciation/v2/fragrant-aru6-ced2ee26.mp3\", \"/storage/v1/object/public/pronunciation/v2/fragrant-aru10-ced2ee26.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/fragrant-aru9-ced2ee26.mp3\", \"/storage/v1/object/public/pronunciation/v2/fragrant-aru3-ced2ee26.mp3\", \"/storage/v1/object/public/pronunciation/v2/fragrant-aru7-ced2ee26.mp3\", \"/storage/v1/object/public/pronunciation/v2/fragrant-aru8-ced2ee26.mp3\", \"/storage/v1/object/public/pronunciation/v2/fragrant-aru2-ced2ee26.mp3\"]}, \"us\": {\"nu\": [\"/s