('2b7e2d47-9440-5055-8e74-fdbc8473e35c', '51593eab-afc9-5ad7-9776-2e5deeada393', '452c5042-759c-590c-a746-986435d7bf30', '81939e19-cbc4-50fa-b2a3-63a4a18a63c2', 'stream', 'UK: /striːm/ | US: /strim/', 'B2', 'verb', 'phát trực tuyến', 'to transmit continuous digital audio or video content over the internet for immediate viewing.', 'The conference will be streamed live online.', 'Hội nghị sẽ được phát trực tiếp trực tuyến.', '{\"en\": \"The press conference will be streamed live on the company\'s official website.\", \"vi\": \"Buổi họp báo sẽ được phát trực tuyến trên trang web chính thức của công ty.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/stream-ljspeech-c82e3d72.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/stream-cori-c82e3d72.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/stream-4ef08446.webp', '[\"broadcast\", \"transmit\", \"telecast\"]', NULL, '[{\"phrase\": \"stream live\", \"meaning\": \"phát trực tiếp\"}, {\"phrase\": \"stream video content\", \"meaning\": \"phát trực tuyến nội dung video\"}]', NULL, '[{\"pos\": \"noun\", \"word\": \"stream\"}, {\"pos\": \"noun\", \"word\": \"streaming\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/stream-cori-c82e3d72.mp3\", \"/storage/v1/object/public/pronunciation/v2/stream-aru0-c82e3d72.mp3\", \"/storage/v1/object/public/pronunciation/v2/stream-aru5-c82e3d72.mp3\", \"/storage/v1/object/public/pronunciation/v2/stream-aru6-c82e3d72.mp3\", \"/storage/v1/object/public/pronunciation/v2/stream-aru10-c82e3d72.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/stream-aru9-c82e3d72.mp3\", \"/storage/v1/object/public/pronunciation/v2/stream-aru3-c82e3d72.mp3\", \"/storage/v1/object/public/pronunciation/v2/stream-aru7-c82e3d72.mp3\", \"/storage/v1/object/public/pronunciation/v2/stream-aru8-c82e3d72.mp3\", \"/storage/v1/object/public/pronunciation/v2/stream-aru2-c82e3d72.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciat