('b22982a6-1d19-50cf-827e-aab51b476742', '51593eab-afc9-5ad7-9776-2e5deeada393', '4bb38d7b-3bd1-55c4-9bfa-c87e13ae418b', '7fe13fca-6c64-51e9-a720-a2669210a35f', 'reprimand', '/ˈreprɪmɑːnd/', 'C1', 'noun', 'Lời quở trách hoặc khiển trách chính thức.', 'an official statement of disapproval given to someone who made a mistake.', 'The employee received a formal reprimand for consistently being late to work.', 'Người nhân viên đã nhận một lời khiển trách chính thức vì liên tục đi làm muộn.', '{\"en\": \"The supervisor issued a written reprimand after the clerk violated office security rules.\", \"vi\": \"Người giám sát đã đưa ra một lời khiển trách bằng văn bản sau khi nhân viên vi phạm quy tắc an ninh.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/reprimand-ljspeech-9501a6ed.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/reprimand-cori-9501a6ed.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/reprimand-85e0805c.webp', '[\"rebuke\", \"censure\", \"reproach\"]', '[\"praise\", \"commendation\"]', '[{\"phrase\": \"formal reprimand\", \"meaning\": \"lời khiển trách chính thức\"}, {\"phrase\": \"written reprimand\", \"meaning\": \"bản khiển trách bằng văn bản\"}]', '[{\"word\": \"reproach\", \"note_vi\": \"Reprimand mang tính chính thức, công sở hơn reproach.\"}]', '[{\"pos\": \"verb\", \"word\": \"reprimand\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/reprimand-cori-9501a6ed.mp3\", \"/storage/v1/object/public/pronunciation/v2/reprimand-aru0-9501a6ed.mp3\", \"/storage/v1/object/public/pronunciation/v2/reprimand-aru5-9501a6ed.mp3\", \"/storage/v1/object/public/pronunciation/v2/reprimand-aru6-9501a6ed.mp3\", \"/storage/v1/object/public/pronunciation/v2/reprimand-aru10-9501a6ed.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/reprimand-aru9-9501a6ed.mp3\", \"/storage/v1/object/public/pronunciation/v2/reprimand-aru3-9501a6ed.mp3\", \"/storage/v1/object/public/pronunciation/v2/reprimand-ar