('fbeb7b5a-d6c2-5fa8-bf6c-d3a1d1ab74b9', '51593eab-afc9-5ad7-9776-2e5deeada393', '56219406-3c9a-5857-a92f-77dc52f21938', 'b39984ce-d55b-58dd-8ea2-0c0f6e52ecd7', 'baggage', 'UK: /ˈbæɡɪdʒ/ | US: /ˈbæɡɪdʒ/', 'B1', 'noun', 'hành lý', 'cases, bags, and luggage containing personal belongings carried by a person during a trip', 'Passengers must check their baggage before boarding.', 'Hành khách phải kiểm tra hành lý của họ trước khi lên máy bay.', '{\"en\": \"Passengers are advised to retrieve their baggage from carousel 3 after landing.\", \"vi\": \"Hành khách được khuyên nên lấy hành lý của mình từ băng chuyền số 3 sau khi hạ cánh.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/baggage-ljspeech-feb52290.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/baggage-cori-feb52290.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/baggage-ab81d34b.webp', '[\"luggage\", \"belongings\", \"bags\"]', NULL, '[{\"phrase\": \"baggage claim area\", \"meaning\": \"khu vực nhận hành lý\"}, {\"phrase\": \"excess baggage fee\", \"meaning\": \"phí hành lý quá cước\"}, {\"phrase\": \"hand baggage\", \"meaning\": \"hành lý xách tay\"}]', '[{\"word\": \"luggage\", \"note_vi\": \"Luggage và baggage đồng nghĩa (đều không đếm được), nhưng baggage phổ biến hơn trong tiếng Anh-Mỹ và ngành hàng không.\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/baggage-cori-feb52290.mp3\", \"/storage/v1/object/public/pronunciation/v2/baggage-aru0-feb52290.mp3\", \"/storage/v1/object/public/pronunciation/v2/baggage-aru5-feb52290.mp3\", \"/storage/v1/object/public/pronunciation/v2/baggage-aru6-feb52290.mp3\", \"/storage/v1/object/public/pronunciation/v2/baggage-aru10-feb52290.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/baggage-aru9-feb52290.mp3\", \"/storage/v1/object/public/pronunciation/v2/baggage-aru3-feb52290.mp3\", \"/storage/v1/object/public/pronunciation/v2/baggage-aru7-feb52290.mp3\", \"/storage/v1/object/public/