('c83fa357-3552-5759-a2f1-a116f9cec75d', '51593eab-afc9-5ad7-9776-2e5deeada393', '57d4e690-b28e-5129-a3e2-7c72a603154d', '3833f0a0-07e0-5c6d-96ed-fcfcd2b846f1', 'checklist', 'UK: /ˈtʃɛklɪst/ | US: /ˈtʃɛklɪst/', 'B1', 'noun', 'danh sách kiểm tra', 'a detailed list of tasks or items requiring completion, verification, or attention.', 'Please refer to the checklist for all required tasks.', 'Vui lòng tham khảo danh sách kiểm tra cho tất cả các nhiệm vụ cần thiết.', '{\"en\": \"The project manager created a safety checklist for the construction site.\", \"vi\": \"Quản lý dự án đã tạo một danh sách kiểm tra an toàn cho công trường xây dựng.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/checklist-ljspeech-ff744cd0.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/checklist-cori-ff744cd0.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/checklist-d78d2c86.webp', '[\"inventory list\", \"task list\", \"to-do list\"]', NULL, '[{\"phrase\": \"safety checklist\", \"meaning\": \"danh sách kiểm tra an toàn\"}, {\"phrase\": \"pre-event checklist\", \"meaning\": \"danh sách kiểm tra trước sự kiện\"}, {\"phrase\": \"complete the checklist\", \"meaning\": \"hoàn thành danh sách kiểm tra\"}]', NULL, NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/checklist-cori-ff744cd0.mp3\", \"/storage/v1/object/public/pronunciation/v2/checklist-aru0-ff744cd0.mp3\", \"/storage/v1/object/public/pronunciation/v2/checklist-aru5-ff744cd0.mp3\", \"/storage/v1/object/public/pronunciation/v2/checklist-aru6-ff744cd0.mp3\", \"/storage/v1/object/public/pronunciation/v2/checklist-aru10-ff744cd0.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/checklist-aru9-ff744cd0.mp3\", \"/storage/v1/object/public/pronunciation/v2/checklist-aru3-ff744cd0.mp3\", \"/storage/v1/object/public/pronunciation/v2/checklist-aru7-ff744cd0.mp3\", \"/storage/v1/object/public/pronunciation/v2/checklist-aru8-ff744cd0.mp3\", \"/storage/v1/object/public/p