('db61fc1a-0335-5bd9-b4b6-8c4bb8b72bee', '51593eab-afc9-5ad7-9776-2e5deeada393', '5d9abbf3-d065-5bfc-9128-334fa05a91dc', '94cba643-785f-5764-835b-1c72727d5172', 'unfavorable', '/ʌnˈfeɪvərəbl/', 'B2', 'adjective', 'không thuận lợi, bất lợi; không tán thành.', 'not good or likely to help you, or showing that you do not approve.', 'The company decided not to expand due to unfavorable market conditions.', 'Công ty quyết định không mở rộng do điều kiện thị trường không thuận lợi.', '{\"en\": \"The project was delayed due to unfavorable weather conditions at the construction site.\", \"vi\": \"Dự án đã bị trì hoãn do điều kiện thời tiết không thuận lợi tại công trường xây dựng.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/unfavorable-ljspeech-02f4c7cc.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/unfavorable-cori-02f4c7cc.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/unfavorable-918f6d9b.webp', '[\"adverse\", \"disadvantageous\", \"negative\"]', '[\"favorable\", \"advantageous\"]', '[{\"phrase\": \"unfavorable conditions\", \"meaning\": \"điều kiện không thuận lợi\"}, {\"phrase\": \"unfavorable review\", \"meaning\": \"đánh giá không tốt\"}]', NULL, '[{\"pos\": \"noun\", \"word\": \"favor\"}, {\"pos\": \"adjective\", \"word\": \"favorable\"}, {\"pos\": \"adverb\", \"word\": \"favorably\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/unfavorable-cori-02f4c7cc.mp3\", \"/storage/v1/object/public/pronunciation/v2/unfavorable-aru0-02f4c7cc.mp3\", \"/storage/v1/object/public/pronunciation/v2/unfavorable-aru5-02f4c7cc.mp3\", \"/storage/v1/object/public/pronunciation/v2/unfavorable-aru6-02f4c7cc.mp3\", \"/storage/v1/object/public/pronunciation/v2/unfavorable-aru10-02f4c7cc.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/unfavorable-aru9-02f4c7cc.mp3\", \"/storage/v1/object/public/pronunciation/v2/unfavorable-aru3-02f4c7cc.mp3\", \"/storage/v1/object/public/pronunciation/v2/unfavorable-