('109945eb-37d9-566a-9829-58ee33fbc6a4', '51593eab-afc9-5ad7-9776-2e5deeada393', '5d9abbf3-d065-5bfc-9128-334fa05a91dc', '94cba643-785f-5764-835b-1c72727d5172', 'relatively', 'UK: /ˈrɛlətɪvli/ | US: /ˈrɛlətɪvli/', 'B2', 'adverb', 'tương đối', 'to a moderate degree when evaluated in comparison with other similar items or standards.', 'The task was relatively easy to complete.', 'Nhiệm vụ tương đối dễ hoàn thành.', '{\"en\": \"The new software application is relatively easy to use compared to the previous system.\", \"vi\": \"Ứng dụng phần mềm mới tương đối dễ sử dụng so với hệ thống trước đó.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/relatively-ljspeech-8cd56185.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/relatively-cori-8cd56185.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/relatively-1e67c81f.webp', '[\"comparatively\", \"moderately\", \"somewhat\"]', '[\"extremely\", \"absolutely\"]', '[{\"phrase\": \"relatively simple\", \"meaning\": \"tương đối đơn giản\"}, {\"phrase\": \"relatively low cost\", \"meaning\": \"chi phí tương đối thấp\"}]', '[{\"word\": \"relevant\", \"note_vi\": \"Relevant là thích hợp/liên quan, còn relatively là tương đối.\"}]', '[{\"pos\": \"adjective\", \"word\": \"relative\"}, {\"pos\": \"verb\", \"word\": \"relate\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/relatively-cori-8cd56185.mp3\", \"/storage/v1/object/public/pronunciation/v2/relatively-aru0-8cd56185.mp3\", \"/storage/v1/object/public/pronunciation/v2/relatively-aru5-8cd56185.mp3\", \"/storage/v1/object/public/pronunciation/v2/relatively-aru6-8cd56185.mp3\", \"/storage/v1/object/public/pronunciation/v2/relatively-aru10-8cd56185.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/relatively-aru9-8cd56185.mp3\", \"/storage/v1/object/public/pronunciation/v2/relatively-aru3-8cd56185.mp3\", \"/storage/v1/object/public/pronunciation/v2/relatively-aru7-8cd56185.mp3\", \"/storage/v1/object/pub