('03e623e1-edbd-5eb6-8576-c438750787fe', '51593eab-afc9-5ad7-9776-2e5deeada393', '5f158ac7-1af3-5548-84ad-9d1cf7b2d95c', '993e9c4e-cc08-595e-9da8-756dcc96db5f', 'counter', 'UK: /ˈkaʊntər/ | US: /ˈkaʊntər/', 'B1', 'noun', 'quầy (hàng, lễ tân)', 'a long flat surface over which goods are sold or business is transacted', 'Please place the items on the counter.', 'Vui lòng đặt các món đồ lên quầy.', '{\"en\": \"Passengers should present their passports at the check-in counter upon arrival.\", \"vi\": \"Hành khách nên xuất trình hộ chiếu tại quầy làm thủ tục khi đến nơi.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/counter-ljspeech-458796e4.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/counter-cori-458796e4.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/counter-4ab58ce4.webp', '[\"desk\", \"table\", \"stand\", \"booth\"]', NULL, '[{\"phrase\": \"check-in counter\", \"meaning\": \"quầy làm thủ tục\"}, {\"phrase\": \"service counter\", \"meaning\": \"quầy phục vụ khách hàng\"}, {\"phrase\": \"over the counter\", \"meaning\": \"bán trực tiếp tại quầy\"}]', '[{\"word\": \"encounter\", \"note_vi\": \"bắt gặp, chạm chán (động từ)\"}]', '[{\"pos\": \"verb\", \"word\": \"counter\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/counter-cori-458796e4.mp3\", \"/storage/v1/object/public/pronunciation/v2/counter-aru0-458796e4.mp3\", \"/storage/v1/object/public/pronunciation/v2/counter-aru5-458796e4.mp3\", \"/storage/v1/object/public/pronunciation/v2/counter-aru6-458796e4.mp3\", \"/storage/v1/object/public/pronunciation/v2/counter-aru10-458796e4.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/counter-aru9-458796e4.mp3\", \"/storage/v1/object/public/pronunciation/v2/counter-aru3-458796e4.mp3\", \"/storage/v1/object/public/pronunciation/v2/counter-aru7-458796e4.mp3\", \"/storage/v1/object/public/pronunciation/v2/counter-aru8-458796e4.mp3\", \"/storage/v1/object/public/pronunciation/v2/counter-ar