('364b5957-572d-5059-82f5-e4a537470d1a', '51593eab-afc9-5ad7-9776-2e5deeada393', '60573bd3-db5e-5bbc-98fa-6581611106ce', 'd8266d07-9783-5eb0-8a88-929dd4aa1f53', 'commercial', 'UK: /kəˈmɜːʃəl/ | US: /kəˈmɜrʃəl/', 'B1', 'adjective', 'thương mại', 'relating to the buying and selling of goods and services for profit', 'They are developing a new commercial building.', 'Họ đang phát triển một tòa nhà thương mại mới.', '{\"en\": \"The district has transformed from a quiet neighborhood into a busy commercial hub.\", \"vi\": \"Khu vực này đã biến đổi từ một xóm nhỏ yên tĩnh thành một trung tâm thương mại sầm uất.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/commercial-ljspeech-f8ef5300.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/commercial-cori-f8ef5300.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/commercial-1dbba138.webp', '[\"business-related\", \"mercantile\", \"trade-related\"]', '[\"non-profit\", \"residential\"]', '[{\"phrase\": \"commercial property\", \"meaning\": \"bất động sản thương mại\"}, {\"phrase\": \"commercial break\", \"meaning\": \"thời gian tạm dừng để phát quảng cáo\"}]', NULL, '[{\"pos\": \"noun\", \"word\": \"commerce\"}, {\"pos\": \"adverb\", \"word\": \"commercially\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/commercial-cori-f8ef5300.mp3\", \"/storage/v1/object/public/pronunciation/v2/commercial-aru0-f8ef5300.mp3\", \"/storage/v1/object/public/pronunciation/v2/commercial-aru5-f8ef5300.mp3\", \"/storage/v1/object/public/pronunciation/v2/commercial-aru6-f8ef5300.mp3\", \"/storage/v1/object/public/pronunciation/v2/commercial-aru10-f8ef5300.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/commercial-aru9-f8ef5300.mp3\", \"/storage/v1/object/public/pronunciation/v2/commercial-aru3-f8ef5300.mp3\", \"/storage/v1/object/public/pronunciation/v2/commercial-aru7-f8ef5300.mp3\", \"/storage/v1/object/public/pronunciation/v2/commercial-aru8-f8ef5300.mp3\", \"/stor