('1b73f86a-5b33-5480-852f-8a584c6a9b44', '51593eab-afc9-5ad7-9776-2e5deeada393', '6585582b-63d1-5286-960f-f8e7f5f7240a', 'cf765965-6895-5d99-8602-fa63349e5bb3', 'accurately', 'UK: /ˈækjʊrətli/ | US: /ˈækjərətli/', 'B2', 'adverb', 'một cách chính xác', 'in a manner that is correct, precise, and completely free from error', 'Please measure the dimensions accurately for the report.', 'Vui lòng đo kích thước chính xác cho báo cáo.', '{\"en\": \"The new software program can accurately predict quarterly sales based on market trends.\", \"vi\": \"Phần mềm mới có thể dự đoán chính xác doanh số hàng quý dựa trên các xu hướng thị trường.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/accurately-ljspeech-659e5375.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/accurately-cori-659e5375.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/accurately-2770461c.webp', '[\"precisely\", \"correctly\", \"exactly\"]', '[\"inaccurately\", \"incorrectly\"]', '[{\"phrase\": \"accurately reflect\", \"meaning\": \"phản ánh chính xác\"}, {\"phrase\": \"accurately calculate\", \"meaning\": \"tính toán chính xác\"}]', NULL, '[{\"pos\": \"adjective\", \"word\": \"accurate\"}, {\"pos\": \"noun\", \"word\": \"accuracy\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/accurately-cori-659e5375.mp3\", \"/storage/v1/object/public/pronunciation/v2/accurately-aru0-659e5375.mp3\", \"/storage/v1/object/public/pronunciation/v2/accurately-aru5-659e5375.mp3\", \"/storage/v1/object/public/pronunciation/v2/accurately-aru6-659e5375.mp3\", \"/storage/v1/object/public/pronunciation/v2/accurately-aru10-659e5375.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/accurately-aru9-659e5375.mp3\", \"/storage/v1/object/public/pronunciation/v2/accurately-aru3-659e5375.mp3\", \"/storage/v1/object/public/pronunciation/v2/accurately-aru7-659e5375.mp3\", \"/storage/v1/object/public/pronunciation/v2/accurately-aru8-659e5375.mp3\", \"/storage/v1/o