('4130a430-2a41-51e1-bd21-236fe1995b3c', '51593eab-afc9-5ad7-9776-2e5deeada393', '69376c09-8801-598b-aeef-d2bdc69acd49', '62641004-099b-5fea-84c9-011df99d95b5', 'scold', '/skəʊld/', 'B1', 'verb', 'khiển trách ai đó một cách giận dữ vì hành động sai trái.', 'to speak angrily to someone because they have done something wrong.', 'The teacher had to scold the noisy students for disrupting the class.', 'Giáo viên đã phải mắng mỏ những học sinh ồn ào vì làm gián đoạn lớp học.', '{\"en\": \"The supervisor will scold workers who ignore the safety protocol in the factory.\", \"vi\": \"Giám sát sẽ khiển trách công nhân bỏ qua quy trình an toàn trong nhà máy.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/scold-ljspeech-46727cb0.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/scold-cori-46727cb0.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/scold-3aab2483.webp', '[\"reprimand\", \"rebuke\", \"berate\"]', '[\"praise\", \"commend\"]', '[{\"phrase\": \"scold someone for\", \"meaning\": \"khiển trách ai vì\"}, {\"phrase\": \"scold harshly\", \"meaning\": \"khiển trách gay gắt\"}, {\"phrase\": \"scold publicly\", \"meaning\": \"khiển trách công khai\"}]', '[{\"word\": \"scare\", \"note_vi\": \"scare là làm sợ, scold là mắng.\"}]', '[{\"pos\": \"noun\", \"word\": \"scolding\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/scold-cori-46727cb0.mp3\", \"/storage/v1/object/public/pronunciation/v2/scold-aru0-46727cb0.mp3\", \"/storage/v1/object/public/pronunciation/v2/scold-aru5-46727cb0.mp3\", \"/storage/v1/object/public/pronunciation/v2/scold-aru6-46727cb0.mp3\", \"/storage/v1/object/public/pronunciation/v2/scold-aru10-46727cb0.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/scold-aru9-46727cb0.mp3\", \"/storage/v1/object/public/pronunciation/v2/scold-aru3-46727cb0.mp3\", \"/storage/v1/object/public/pronunciation/v2/scold-aru7-46727cb0.mp3\", \"/storage/v1/object/public/pronunciation/v2/scold-aru