('714a85ed-ad3e-5488-8762-58991faaeca9', '51593eab-afc9-5ad7-9776-2e5deeada393', '69376c09-8801-598b-aeef-d2bdc69acd49', '62641004-099b-5fea-84c9-011df99d95b5', 'agreement', 'UK: /əˈɡriːmənt/ | US: /əˈɡriːmənt/', 'B1', 'noun', 'thỏa thuận, hợp đồng', 'a negotiated arrangement between parties regarding a course of action or business terms.', 'The two companies will enter into a new agreement next week.', 'Hai công ty sẽ ký kết một thỏa thuận mới vào tuần tới.', '{\"en\": \"The legal department is drafting the final agreement for the merger.\", \"vi\": \"Bộ phận pháp lý đang soạn thảo bản thỏa thuận cuối cùng cho việc sáp nhập.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/agreement-ljspeech-c0e57121.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/agreement-cori-c0e57121.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/agreement-d5eb901d.webp', '[\"contract\", \"pact\", \"accord\", \"settlement\"]', '[\"disagreement\", \"dispute\"]', '[{\"phrase\": \"reach an agreement\", \"meaning\": \"đạt được thỏa thuận\"}, {\"phrase\": \"sign an agreement\", \"meaning\": \"ký kết thỏa thuận\"}, {\"phrase\": \"binding agreement\", \"meaning\": \"thỏa thuận có tính ràng buộc pháp lý\"}]', '[{\"word\": \"contract\", \"note_vi\": \"Contract luôn mang tính chất văn bản pháp lý chính thức, agreement mang nghĩa rộng hơn bao gồm cả thỏa thuận miệng.\"}]', '[{\"pos\": \"verb\", \"word\": \"agree\"}, {\"pos\": \"adjective\", \"word\": \"agreeable\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/agreement-cori-c0e57121.mp3\", \"/storage/v1/object/public/pronunciation/v2/agreement-aru0-c0e57121.mp3\", \"/storage/v1/object/public/pronunciation/v2/agreement-aru5-c0e57121.mp3\", \"/storage/v1/object/public/pronunciation/v2/agreement-aru6-c0e57121.mp3\", \"/storage/v1/object/public/pronunciation/v2/agreement-aru10-c0e57121.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/agreement-aru9-c0e57121.mp3\", \"/stora