('a65724ea-4cf0-52fd-b4d1-73040d9ed624', '51593eab-afc9-5ad7-9776-2e5deeada393', '6e33e33b-2d81-500d-b77a-25edd47ca90a', 'db2d5826-d322-5dbc-ace4-d14575e07673', 'avenue', 'UK: /ˈævəˌnjuː/ | US: /ˈævəˌnuː/', 'B1', 'noun', 'đại lộ', 'a broad public street or thoroughfare, often lined with trees or major commercial buildings', 'The new office is located on a busy avenue.', 'Văn phòng mới nằm trên một đại lộ sầm uất.', '{\"en\": \"The new branch office is located at the intersection of Grand Avenue and Main Street.\", \"vi\": \"Văn phòng chi nhánh mới nằm ở ngã tư Đại lộ Grand và Phố Main.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/avenue-ljspeech-fccce48f.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/avenue-cori-fccce48f.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/avenue-13597671.webp', '[\"boulevard\", \"thoroughfare\", \"street\", \"way\"]', NULL, '[{\"phrase\": \"explore new avenues\", \"meaning\": \"khám phá những hướng đi/giải pháp mới\"}, {\"phrase\": \"avenue for growth\", \"meaning\": \"con đường phát triển\"}]', '[{\"word\": \"revenue\", \"note_vi\": \"doanh thu (tài chính), phát âm và cách viết gần tương tự avenue\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/avenue-cori-fccce48f.mp3\", \"/storage/v1/object/public/pronunciation/v2/avenue-aru0-fccce48f.mp3\", \"/storage/v1/object/public/pronunciation/v2/avenue-aru5-fccce48f.mp3\", \"/storage/v1/object/public/pronunciation/v2/avenue-aru6-fccce48f.mp3\", \"/storage/v1/object/public/pronunciation/v2/avenue-aru10-fccce48f.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/avenue-aru9-fccce48f.mp3\", \"/storage/v1/object/public/pronunciation/v2/avenue-aru3-fccce48f.mp3\", \"/storage/v1/object/public/pronunciation/v2/avenue-aru7-fccce48f.mp3\", \"/storage/v1/object/public/pronunciation/v2/avenue-aru8-fccce48f.mp3\", \"/storage/v1/object/public/pronunciation/v2/avenue-aru2-fccce48f.mp3\"]}, \"us\": {\"nu\": [\"/st