('ea2fb169-d46e-55fb-bc87-4203dbf2ea3c', '51593eab-afc9-5ad7-9776-2e5deeada393', '7489d6b6-b7b3-5509-8b04-7b6531321da0', '81e7ce2a-f020-5392-b14f-0f94b2fd9654', 'announcement', 'UK: /əˈnaʊns.mənt/ | US: /əˈnaʊns.mənt/', 'B1', 'noun', 'thông báo', 'a formal public statement giving information about something that has happened or will happen.', 'They made an announcement about the new policy.', 'Họ đã đưa ra một thông báo về chính sách mới.', '{\"en\": \"An important announcement regarding the office relocation will be posted on the intranet today.\", \"vi\": \"Một thông báo quan trọng về việc chuyển văn phòng sẽ được đăng trên mạng nội bộ hôm nay.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/announcement-ljspeech-bd633590.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/announcement-cori-bd633590.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/announcement-9e0ad1c8.webp', '[\"notice\", \"statement\", \"declaration\", \"bulletin\"]', NULL, '[{\"phrase\": \"make an announcement\", \"meaning\": \"đưa ra thông báo\"}, {\"phrase\": \"formal announcement\", \"meaning\": \"thông báo chính thức\"}, {\"phrase\": \"public announcement\", \"meaning\": \"thông báo công cộng\"}]', NULL, '[{\"pos\": \"verb\", \"word\": \"announce\"}, {\"pos\": \"noun\", \"word\": \"announcer\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/announcement-cori-bd633590.mp3\", \"/storage/v1/object/public/pronunciation/v2/announcement-aru0-bd633590.mp3\", \"/storage/v1/object/public/pronunciation/v2/announcement-aru5-bd633590.mp3\", \"/storage/v1/object/public/pronunciation/v2/announcement-aru6-bd633590.mp3\", \"/storage/v1/object/public/pronunciation/v2/announcement-aru10-bd633590.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/announcement-aru9-bd633590.mp3\", \"/storage/v1/object/public/pronunciation/v2/announcement-aru3-bd633590.mp3\", \"/storage/v1/object/public/pronunciation/v2/announcement-aru7-bd633590.mp3