('2f3e2f27-934b-545f-b5b3-4f3a2bf7e30c', '51593eab-afc9-5ad7-9776-2e5deeada393', '78c60784-bab8-5077-9838-783e2bb54130', 'e4c22dff-4779-573a-9a0c-95725d92f63a', 'fabricate', '/ˈfæbrɪkeɪt/', 'C2', 'verb', 'tạo ra, chế tạo một sản phẩm hoặc cấu trúc.', 'to produce or make goods or equipment from various materials.', 'The company specializes in fabricating custom metal parts.', 'Công ty chuyên chế tạo các bộ phận kim loại theo yêu cầu.', '{\"en\": \"The factory is equipped to fabricate complex metal components for aircraft.\", \"vi\": \"Nhà máy được trang bị để chế tạo các linh kiện kim loại phức tạp cho máy bay.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/fabricate-ljspeech-41c079fd.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/fabricate-cori-41c079fd.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/fabricate-602fa454.webp', '[\"manufacture\", \"construct\", \"produce\"]', '[\"destroy\", \"dismantle\"]', '[{\"phrase\": \"fabricate parts\", \"meaning\": \"chế tạo các bộ phận\"}, {\"phrase\": \"fabricate steel\", \"meaning\": \"chế tạo thép\"}]', '[{\"word\": \"fabricate\", \"note_vi\": \"Nghĩa khác là bịa đặt thông tin, tránh nhầm với sản xuất thông thường.\"}]', '[{\"pos\": \"noun\", \"word\": \"fabrication\"}, {\"pos\": \"noun\", \"word\": \"fabricator\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/fabricate-cori-41c079fd.mp3\", \"/storage/v1/object/public/pronunciation/v2/fabricate-aru0-41c079fd.mp3\", \"/storage/v1/object/public/pronunciation/v2/fabricate-aru5-41c079fd.mp3\", \"/storage/v1/object/public/pronunciation/v2/fabricate-aru6-41c079fd.mp3\", \"/storage/v1/object/public/pronunciation/v2/fabricate-aru10-41c079fd.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/fabricate-aru9-41c079fd.mp3\", \"/storage/v1/object/public/pronunciation/v2/fabricate-aru3-41c079fd.mp3\", \"/storage/v1/object/public/pronunciation/v2/fabricate-aru7-41c079fd.mp3\", \"/storage/v1/object/publi