('f0527fc9-0152-5199-946d-e7e0ac839505', '51593eab-afc9-5ad7-9776-2e5deeada393', '7a879fba-e78a-57d5-b640-a82959b20f00', '858699eb-b538-5735-8eec-215cfdcb32bb', 'status', 'UK: /ˈsteɪtəs/ | US: /ˈstætəs/', 'B2', 'noun', 'trạng thái', 'the current condition or state of a situation, process, or ongoing activity at a specific time.', 'The project status is updated weekly.', 'Trạng thái dự án được cập nhật hàng tuần.', '{\"en\": \"Please check the delivery status of order number 405 using the online tracking system.\", \"vi\": \"Vui lòng kiểm tra trạng thái giao hàng của đơn hàng số 405 bằng hệ thống theo dõi trực tuyến.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/status-ljspeech-48a3661d.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/status-cori-48a3661d.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/status-51717da7.webp', '[\"condition\", \"state\", \"position\"]', NULL, '[{\"phrase\": \"status report\", \"meaning\": \"báo cáo tiến độ/trạng thái\"}, {\"phrase\": \"current status\", \"meaning\": \"trạng thái hiện tại\"}]', '[{\"word\": \"statute\", \"note_vi\": \"đạo luật, quy chế (khác với status là trạng thái/vị thế)\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/status-cori-48a3661d.mp3\", \"/storage/v1/object/public/pronunciation/v2/status-aru0-48a3661d.mp3\", \"/storage/v1/object/public/pronunciation/v2/status-aru5-48a3661d.mp3\", \"/storage/v1/object/public/pronunciation/v2/status-aru6-48a3661d.mp3\", \"/storage/v1/object/public/pronunciation/v2/status-aru10-48a3661d.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/status-aru9-48a3661d.mp3\", \"/storage/v1/object/public/pronunciation/v2/status-aru3-48a3661d.mp3\", \"/storage/v1/object/public/pronunciation/v2/status-aru7-48a3661d.mp3\", \"/storage/v1/object/public/pronunciation/v2/status-aru8-48a3661d.mp3\", \"/storage/v1/object/public/pronunciation/v2/status-aru2-48a3661d.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/ob