('7c1582d4-1b1c-5d6c-9130-8203ff104442', '51593eab-afc9-5ad7-9776-2e5deeada393', '80496d89-b7bd-53e1-a9ed-eab952a49469', '72ad7a19-3ae7-567e-ac2d-cf2c17883d08', 'snout', '/snaʊt/', 'C2', 'noun', 'Phần mũi và miệng nhô ra của một số loài động vật.', 'the long nose and mouth that projects from the face of certain animals.', 'The pig used its snout to dig for truffles in the forest.', 'Con lợn dùng mõm của nó để đào tìm nấm cục trong rừng.', '{\"en\": \"The security dog pointed its long snout toward the suspicious package at the airport.\", \"vi\": \"Chú chó an ninh hướng chiếc mõm dài của nó về phía gói hàng khả nghi tại sân bay.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/snout-ljspeech-0b32a1df.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/snout-cori-0b32a1df.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/snout-1b6ecfa8.webp', '[\"muzzle\", \"nose\"]', NULL, '[{\"phrase\": \"long snout\", \"meaning\": \"mõm dài\"}, {\"phrase\": \"animal\'s snout\", \"meaning\": \"mõm của động vật\"}]', '[{\"word\": \"spout\", \"note_vi\": \"spout là vòi của ấm trà hoặc bình nước\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/snout-cori-0b32a1df.mp3\", \"/storage/v1/object/public/pronunciation/v2/snout-aru0-0b32a1df.mp3\", \"/storage/v1/object/public/pronunciation/v2/snout-aru5-0b32a1df.mp3\", \"/storage/v1/object/public/pronunciation/v2/snout-aru6-0b32a1df.mp3\", \"/storage/v1/object/public/pronunciation/v2/snout-aru10-0b32a1df.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/snout-aru9-0b32a1df.mp3\", \"/storage/v1/object/public/pronunciation/v2/snout-aru3-0b32a1df.mp3\", \"/storage/v1/object/public/pronunciation/v2/snout-aru7-0b32a1df.mp3\", \"/storage/v1/object/public/pronunciation/v2/snout-aru8-0b32a1df.mp3\", \"/storage/v1/object/public/pronunciation/v2/snout-aru2-0b32a1df.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/snout-ljspeech-0b32a1df.mp3\", \"/