('6457d341-8ab4-5806-938b-7fe271a3f962', '51593eab-afc9-5ad7-9776-2e5deeada393', '8804217b-30e4-53bf-be66-81b7aec7e4cb', 'fbf13434-b983-5284-8539-72de5154fbd2', 'attach', 'UK: /əˈtætʃ/ | US: /əˈtætʃ/', 'B1', 'verb', 'đính kèm', 'to connect, join, or fasten one item to another document or message.', 'Please attach the file to your email.', 'Vui lòng đính kèm tệp vào email của bạn.', '{\"en\": \"Please attach your updated resume and cover letter when submitting the application form.\", \"vi\": \"Vui lòng đính kèm sơ yếu lý lịch cập nhật và thư xin việc khi nộp mẫu đơn ứng tuyển.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/attach-ljspeech-13ce071f.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/attach-cori-13ce071f.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/attach-6a616934.webp', '[\"enclose\", \"append\", \"affix\", \"connect\"]', '[\"detach\", \"disconnect\", \"remove\"]', '[{\"phrase\": \"attach a file\", \"meaning\": \"đính kèm một tệp\"}, {\"phrase\": \"attached document\", \"meaning\": \"tài liệu được đính kèm\"}]', '[{\"word\": \"attack\", \"note_vi\": \"Attack nghĩa là tấn công, chú ý đuôi \'ck\' khác với \'ch\' trong attach (đính kèm).\"}]', '[{\"pos\": \"noun\", \"word\": \"attachment\"}, {\"pos\": \"adjective\", \"word\": \"attached\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/attach-cori-13ce071f.mp3\", \"/storage/v1/object/public/pronunciation/v2/attach-aru0-13ce071f.mp3\", \"/storage/v1/object/public/pronunciation/v2/attach-aru5-13ce071f.mp3\", \"/storage/v1/object/public/pronunciation/v2/attach-aru6-13ce071f.mp3\", \"/storage/v1/object/public/pronunciation/v2/attach-aru10-13ce071f.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/attach-aru9-13ce071f.mp3\", \"/storage/v1/object/public/pronunciation/v2/attach-aru3-13ce071f.mp3\", \"/storage/v1/object/public/pronunciation/v2/attach-aru7-13ce071f.mp3\", \"/storage/v1/object/public/pronunciation/v2/attach-aru8-