('439d8500-caaa-5fa3-ac08-0b6c23d17445', '51593eab-afc9-5ad7-9776-2e5deeada393', '89946880-3570-5133-84f6-887ae9625b57', 'f098d7a2-b12d-592d-b618-9a71d25ab346', 'assess', 'UK: /əˈses/ | US: /əˈses/', 'B2', 'verb', 'đánh giá', 'to carefully evaluate or judge the nature, value, quality, or importance of something', 'The manager will assess the risks of the project.', 'Người quản lý sẽ đánh giá các rủi ro của dự án.', '{\"en\": \"The committee will assess the damage caused by the storm before approving repairs.\", \"vi\": \"Ủy ban sẽ đánh giá thiệt hại do cơn bão gây ra trước khi phê duyệt sửa chữa.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/assess-ljspeech-e910868a.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/assess-cori-e910868a.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/assess-b03be3bf.webp', '[\"evaluate\", \"appraise\", \"estimate\", \"judge\"]', '[\"ignore\", \"neglect\"]', '[{\"phrase\": \"assess damage\", \"meaning\": \"đánh giá thiệt hại\"}, {\"phrase\": \"assess the impact\", \"meaning\": \"đánh giá tác động\"}]', '[{\"word\": \"access\", \"note_vi\": \"truy cập hoặc quyền truy cập (phát âm khá giống nhưng nghĩa hoàn toàn khác).\"}, {\"word\": \"excess\", \"note_vi\": \"sự vượt quá, sự dư thừa.\"}]', '[{\"pos\": \"noun\", \"word\": \"assessment\"}, {\"pos\": \"noun\", \"word\": \"assessor\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/assess-cori-e910868a.mp3\", \"/storage/v1/object/public/pronunciation/v2/assess-aru0-e910868a.mp3\", \"/storage/v1/object/public/pronunciation/v2/assess-aru5-e910868a.mp3\", \"/storage/v1/object/public/pronunciation/v2/assess-aru6-e910868a.mp3\", \"/storage/v1/object/public/pronunciation/v2/assess-aru10-e910868a.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/assess-aru9-e910868a.mp3\", \"/storage/v1/object/public/pronunciation/v2/assess-aru3-e910868a.mp3\", \"/storage/v1/object/public/pronunciation/v2/assess-aru7-e910868a.mp3\