('1ed6ba64-43f5-5ad3-bdc3-0009bfb10ea7', '51593eab-afc9-5ad7-9776-2e5deeada393', '8fdec5e4-2958-5a70-8691-366a925278ab', '7847ed3c-550e-5595-987a-3409ce7c0075', 'ahead of', 'UK: /əˈhɛd əv/ | US: /əˈhɛd əv/', 'B1', 'preposition', 'trước', 'further forward in space or earlier in time than someone or something else.', 'The project was completed ahead of schedule.', 'Dự án đã hoàn thành trước thời hạn.', '{\"en\": \"The construction team finished renovating the main hall ahead of schedule.\", \"vi\": \"Đội thi công đã hoàn thành việc cải tạo sảnh chính trước tiến độ.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/ahead-of-ljspeech-10282280.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/ahead-of-cori-10282280.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/ahead-of-5c879606.webp', '[\"prior to\", \"in advance of\", \"before\"]', '[\"behind\", \"after\"]', '[{\"phrase\": \"ahead of schedule\", \"meaning\": \"sớm hơn dự kiến / kế hoạch\"}, {\"phrase\": \"ahead of time\", \"meaning\": \"trước thời hạn\"}, {\"phrase\": \"ahead of deadline\", \"meaning\": \"trước hạn chót\"}]', '[{\"word\": \"behind\", \"note_vi\": \"Behind schedule nghĩa là trễ tiến độ, ngược nghĩa hoàn toàn với ahead of schedule.\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/ahead-of-cori-10282280.mp3\", \"/storage/v1/object/public/pronunciation/v2/ahead-of-aru0-10282280.mp3\", \"/storage/v1/object/public/pronunciation/v2/ahead-of-aru5-10282280.mp3\", \"/storage/v1/object/public/pronunciation/v2/ahead-of-aru6-10282280.mp3\", \"/storage/v1/object/public/pronunciation/v2/ahead-of-aru10-10282280.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/ahead-of-aru9-10282280.mp3\", \"/storage/v1/object/public/pronunciation/v2/ahead-of-aru3-10282280.mp3\", \"/storage/v1/object/public/pronunciation/v2/ahead-of-aru7-10282280.mp3\", \"/storage/v1/object/public/pronunciation/v2/ahead-of-aru8-10282280.mp3\", \"/storage/v1/object