('a56e201e-4a3c-5ff7-99e2-5ed73715d4fb', '51593eab-afc9-5ad7-9776-2e5deeada393', '9dee1249-c3ac-5ef4-a83e-03499d88c5a6', '7ae20a8f-1008-5f0c-870e-5bc41e90cc76', 'certify', 'UK: /ˈsɜːtɪfaɪd/ | US: /ˈsɜːrtɪfaɪd/', 'B2', 'adjective', 'được chứng nhận', 'Having officially gained a qualification or passed examinations to perform a specific job or task.', 'He is a certified accountant.', 'Anh ấy là một kế toán viên được chứng nhận.', '{\"en\": \"Only certified technicians are authorized to repair the medical equipment.\", \"vi\": \"Chỉ các kỹ thuật viên đã được chứng nhận mới được phép sửa chữa thiết bị y tế.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/certify-ljspeech-3f772e75.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/certify-cori-3f772e75.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/certify-31eeb2c6.webp', '[\"verify\", \"validate\", \"license\", \"endorse\"]', '[\"disqualify\"]', '[{\"phrase\": \"certified public accountant\", \"meaning\": \"kế toán viên công chứng (CPA)\"}, {\"phrase\": \"certify that\", \"meaning\": \"chứng nhận rằng\"}]', NULL, '[{\"pos\": \"noun\", \"word\": \"certificate\"}, {\"pos\": \"noun\", \"word\": \"certification\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/certify-cori-3f772e75.mp3\", \"/storage/v1/object/public/pronunciation/v2/certify-aru0-3f772e75.mp3\", \"/storage/v1/object/public/pronunciation/v2/certify-aru5-3f772e75.mp3\", \"/storage/v1/object/public/pronunciation/v2/certify-aru6-3f772e75.mp3\", \"/storage/v1/object/public/pronunciation/v2/certify-aru10-3f772e75.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/certify-aru9-3f772e75.mp3\", \"/storage/v1/object/public/pronunciation/v2/certify-aru3-3f772e75.mp3\", \"/storage/v1/object/public/pronunciation/v2/certify-aru7-3f772e75.mp3\", \"/storage/v1/object/public/pronunciation/v2/certify-aru8-3f772e75.mp3\", \"/storage/v1/object/public/pronunciation/v2/certify-aru2-3f772e75.mp3\"]},