('cdda4e06-62ef-5356-87ba-d0f5bc76f301', '51593eab-afc9-5ad7-9776-2e5deeada393', 'a2acd23e-8d32-5382-9b3d-ffc10bef5714', '84be45bf-c1b7-51cb-ae73-64d72fafce43', 'further', '/ˈfɜːðə(r)/', 'A2', 'adverb', 'Xa hơn, hoặc ở mức độ lớn hơn; thêm nữa.', 'at or to a greater distance or a more advanced level.', 'We need to discuss this matter further before making a decision.', 'Chúng ta cần thảo luận thêm về vấn đề này trước khi đưa ra quyết định.', '{\"en\": \"Please contact our customer service department if you require further assistance with your order.\", \"vi\": \"Vui lòng liên hệ với bộ phận dịch vụ khách hàng của chúng tôi nếu bạn cần hỗ trợ thêm về đơn hàng của mình.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/further-ljspeech-8aeff27d.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/further-cori-8aeff27d.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/further-66b29761.webp', '[\"additional\", \"more\", \"extra\"]', NULL, '[{\"phrase\": \"further information\", \"meaning\": \"thông tin thêm\"}, {\"phrase\": \"further details\", \"meaning\": \"chi tiết thêm\"}, {\"phrase\": \"further education\", \"meaning\": \"giáo dục nâng cao\"}]', '[{\"word\": \"farther\", \"note_vi\": \"farther chỉ khoảng cách địa lý, further chỉ mức độ hoặc khoảng cách\"}]', '[{\"pos\": \"verb\", \"word\": \"further\"}, {\"pos\": \"noun\", \"word\": \"furtherance\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/further-cori-8aeff27d.mp3\", \"/storage/v1/object/public/pronunciation/v2/further-aru0-8aeff27d.mp3\", \"/storage/v1/object/public/pronunciation/v2/further-aru5-8aeff27d.mp3\", \"/storage/v1/object/public/pronunciation/v2/further-aru6-8aeff27d.mp3\", \"/storage/v1/object/public/pronunciation/v2/further-aru10-8aeff27d.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/further-aru9-8aeff27d.mp3\", \"/storage/v1/object/public/pronunciation/v2/further-aru3-8aeff27d.mp3\", \"/storage/v1/object/public/pron