('f3fe542e-735f-5984-a05d-c96186d3da33', '51593eab-afc9-5ad7-9776-2e5deeada393', 'a8338ad6-6ffa-575c-92e2-edb7f61c74d4', '042eef3e-8434-5338-b286-f76c8437f182', 'based on', 'UK: /beɪst ɒn/ | US: /beɪst ɑn/', 'B1', 'preposition', 'dựa trên, căn cứ vào', 'using particular facts or ideas as the foundation for something.', 'The decision was based on a thorough analysis of the data.', 'Quyết định được đưa ra dựa trên phân tích kỹ lưỡng dữ liệu.', '{\"en\": \"The annual performance bonus is based on individual sales achievements and customer reviews.\", \"vi\": \"Tiền thưởng hiệu suất hàng năm dựa trên thành tích doanh số cá nhân và đánh giá từ khách hàng.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/based-on-ljspeech-98b418d3.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/based-on-cori-98b418d3.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/based-on-ef1e5cc9.webp', '[\"derived from\", \"founded on\", \"resting on\"]', NULL, '[{\"phrase\": \"based on facts\", \"meaning\": \"dựa trên thực tế\"}, {\"phrase\": \"based on performance\", \"meaning\": \"căn cứ vào hiệu suất\"}, {\"phrase\": \"based on feedback\", \"meaning\": \"dựa trên phản hồi\"}]', '[{\"word\": \"according to\", \"note_vi\": \"theo như (nguồn trích dẫn thông tin)\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/based-on-cori-98b418d3.mp3\", \"/storage/v1/object/public/pronunciation/v2/based-on-aru0-98b418d3.mp3\", \"/storage/v1/object/public/pronunciation/v2/based-on-aru5-98b418d3.mp3\", \"/storage/v1/object/public/pronunciation/v2/based-on-aru6-98b418d3.mp3\", \"/storage/v1/object/public/pronunciation/v2/based-on-aru10-98b418d3.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/based-on-aru9-98b418d3.mp3\", \"/storage/v1/object/public/pronunciation/v2/based-on-aru3-98b418d3.mp3\", \"/storage/v1/object/public/pronunciation/v2/based-on-aru7-98b418d3.mp3\", \"/storage/v1/object/public/pronunciation/v2/based-on-aru8-