('4be5b259-84be-5275-b479-68ad68f539cc', '51593eab-afc9-5ad7-9776-2e5deeada393', 'caaedb64-fac2-59ca-ad94-e9ea9156a7b3', '9136058f-d115-5ac3-a832-fd53ab18438d', 'coupon', 'UK: /ˈkuː.pɒn/ | US: /ˈkuː.pɑːn/', 'B1', 'noun', 'phiếu giảm giá', 'a piece of paper or electronic voucher that allows you to pay less money', 'You can get a discount with this coupon.', 'Bạn có thể được giảm giá với phiếu này.', '{\"en\": \"Customers can redeem this discount coupon on their next online purchase.\", \"vi\": \"Khách hàng có thể sử dụng phiếu giảm giá này cho lần mua hàng trực tuyến tiếp theo.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/coupon-ljspeech-f3c8670a.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/coupon-cori-f3c8670a.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/coupon-267bfc48.webp', '[\"voucher\", \"promo code\", \"token\", \"certificate\"]', NULL, '[{\"phrase\": \"discount coupon\", \"meaning\": \"phiếu giảm giá\"}, {\"phrase\": \"redeem a coupon\", \"meaning\": \"đổi/áp dụng phiếu giảm giá\"}]', NULL, NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/coupon-cori-f3c8670a.mp3\", \"/storage/v1/object/public/pronunciation/v2/coupon-aru0-f3c8670a.mp3\", \"/storage/v1/object/public/pronunciation/v2/coupon-aru5-f3c8670a.mp3\", \"/storage/v1/object/public/pronunciation/v2/coupon-aru6-f3c8670a.mp3\", \"/storage/v1/object/public/pronunciation/v2/coupon-aru10-f3c8670a.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/coupon-aru9-f3c8670a.mp3\", \"/storage/v1/object/public/pronunciation/v2/coupon-aru3-f3c8670a.mp3\", \"/storage/v1/object/public/pronunciation/v2/coupon-aru7-f3c8670a.mp3\", \"/storage/v1/object/public/pronunciation/v2/coupon-aru8-f3c8670a.mp3\", \"/storage/v1/object/public/pronunciation/v2/coupon-aru2-f3c8670a.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/coupon-ljspeech-f3c8670a.mp3\", \"/storage/v1/object/public/pronunciation/v2/coupon-lt408-f3c8