('20670e98-6535-531a-8df0-23cebd50ec96', '51593eab-afc9-5ad7-9776-2e5deeada393', 'caaedb64-fac2-59ca-ad94-e9ea9156a7b3', '9136058f-d115-5ac3-a832-fd53ab18438d', 'oversized', '/ˈəʊvəˌsaɪzd/', 'B1', 'adjective', 'Lớn hơn kích thước tiêu chuẩn hoặc bình thường.', 'too large or bigger than the usual size that people normally expect to see.', 'She bought an oversized sweater that looked very comfortable.', 'Cô ấy đã mua một chiếc áo len quá khổ trông rất thoải mái.', '{\"en\": \"The shipping department needs an oversized box to pack the large computer monitor safely.\", \"vi\": \"Bộ phận vận chuyển cần một chiếc hộp quá khổ để đóng gói màn hình máy tính lớn một cách an toàn.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/oversized-ljspeech-76eff77b.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/oversized-cori-76eff77b.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/oversized-3bf78f34.webp', '[\"huge\", \"large\"]', '[\"small\", \"undersized\"]', '[{\"phrase\": \"oversized package\", \"meaning\": \"kiện hàng quá khổ\"}, {\"phrase\": \"oversized load\", \"meaning\": \"hàng hóa quá tải\"}]', NULL, '[{\"pos\": \"noun\", \"word\": \"size\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/oversized-cori-76eff77b.mp3\", \"/storage/v1/object/public/pronunciation/v2/oversized-aru0-76eff77b.mp3\", \"/storage/v1/object/public/pronunciation/v2/oversized-aru5-76eff77b.mp3\", \"/storage/v1/object/public/pronunciation/v2/oversized-aru6-76eff77b.mp3\", \"/storage/v1/object/public/pronunciation/v2/oversized-aru10-76eff77b.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/oversized-aru9-76eff77b.mp3\", \"/storage/v1/object/public/pronunciation/v2/oversized-aru3-76eff77b.mp3\", \"/storage/v1/object/public/pronunciation/v2/oversized-aru7-76eff77b.mp3\", \"/storage/v1/object/public/pronunciation/v2/oversized-aru8-76eff77b.mp3\", \"/storage/v1/object/public/pronunciation/v2/oversized-aru2-76eff77b.mp3\"]}, \