('6dc66e58-66bd-5227-a99e-effef761ed82', '51593eab-afc9-5ad7-9776-2e5deeada393', 'd0a14666-ca27-5b74-be25-13cf87372ff7', 'bc2ad68c-2cbc-5b7a-8efd-8f60591aaaf7', 'secure', 'UK: /sɪˈkjʊə/ | US: /sɪˈkjʊr/', 'B2', 'adjective', 'an toàn, được bảo đảm', 'safe from danger, harm, or unauthorized access by external threats.', 'The data is stored in a secure server to prevent unauthorized access.', 'Dữ liệu được lưu trữ trong một máy chủ an toàn để ngăn chặn truy cập trái phép.', '{\"en\": \"All sensitive financial records must be stored in a secure filing cabinet.\", \"vi\": \"Tất cả các hồ sơ tài chính nhạy cảm phải được lưu trữ trong tủ hồ sơ an toàn.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/secure-ljspeech-d015cc46.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/secure-cori-d015cc46.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/secure-7296fa5d.webp', '[\"safe\", \"protected\", \"stable\"]', '[\"insecure\", \"vulnerable\", \"risky\"]', '[{\"phrase\": \"secure connection\", \"meaning\": \"kết nối an toàn/bảo mật\"}, {\"phrase\": \"secure environment\", \"meaning\": \"môi trường an toàn\"}]', NULL, '[{\"pos\": \"verb\", \"word\": \"secure\"}, {\"pos\": \"noun\", \"word\": \"security\"}, {\"pos\": \"adverb\", \"word\": \"securely\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/secure-cori-d015cc46.mp3\", \"/storage/v1/object/public/pronunciation/v2/secure-aru0-d015cc46.mp3\", \"/storage/v1/object/public/pronunciation/v2/secure-aru5-d015cc46.mp3\", \"/storage/v1/object/public/pronunciation/v2/secure-aru6-d015cc46.mp3\", \"/storage/v1/object/public/pronunciation/v2/secure-aru10-d015cc46.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/secure-aru9-d015cc46.mp3\", \"/storage/v1/object/public/pronunciation/v2/secure-aru3-d015cc46.mp3\", \"/storage/v1/object/public/pronunciation/v2/secure-aru7-d015cc46.mp3\", \"/storage/v1/object/public/pronunciation/v2/secure-aru8-d015cc46.mp3\", \"/st