('72752239-a61f-5f82-8e44-85a72cfca244', '51593eab-afc9-5ad7-9776-2e5deeada393', 'd4e9617e-a282-5e1f-945c-797ec943003f', '46727505-dc1d-5759-9cca-9b1bba157e49', 'rejoice', '/rɪˈdʒɔɪs/', 'C1', 'verb', 'Vui mừng, hân hoan.', 'to feel or show great happiness about something.', 'We all rejoiced when we heard the good news about her recovery.', 'Tất cả chúng tôi đều vui mừng khi nghe tin tốt về sự hồi phục của cô ấy.', '{\"en\": \"The marketing team rejoiced after winning the prestigious advertising contract.\", \"vi\": \"Đội ngũ tiếp thị đã vô cùng vui mừng sau khi giành được hợp đồng quảng cáo danh giá.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/rejoice-ljspeech-349b2288.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/rejoice-cori-349b2288.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/rejoice-4f6d689a.webp', '[\"celebrate\", \"exult\", \"gladden\"]', '[\"mourn\", \"grieve\"]', '[{\"phrase\": \"rejoice at the news\", \"meaning\": \"vui mừng trước tin tức\"}, {\"phrase\": \"rejoice in success\", \"meaning\": \"hân hoan trong thành công\"}]', NULL, '[{\"pos\": \"noun\", \"word\": \"rejoicing\"}, {\"pos\": \"adjective\", \"word\": \"rejoiced\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/rejoice-cori-349b2288.mp3\", \"/storage/v1/object/public/pronunciation/v2/rejoice-aru0-349b2288.mp3\", \"/storage/v1/object/public/pronunciation/v2/rejoice-aru5-349b2288.mp3\", \"/storage/v1/object/public/pronunciation/v2/rejoice-aru6-349b2288.mp3\", \"/storage/v1/object/public/pronunciation/v2/rejoice-aru10-349b2288.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/rejoice-aru9-349b2288.mp3\", \"/storage/v1/object/public/pronunciation/v2/rejoice-aru3-349b2288.mp3\", \"/storage/v1/object/public/pronunciation/v2/rejoice-aru7-349b2288.mp3\", \"/storage/v1/object/public/pronunciation/v2/rejoice-aru8-349b2288.mp3\", \"/storage/v1/object/public/pronunciation/v2/rejoice-aru2-349b2288.mp3\"]}, \"us\": {