('0819dd46-87b2-5a9f-9a4e-0363f1741e58', '51593eab-afc9-5ad7-9776-2e5deeada393', 'd975b600-6bc6-52ce-9bca-95f5bec4ddbc', 'd49e035c-8e71-5c6f-9dd3-eaa466a40e94', 'trait', 'UK: /treɪt/ | US: /treɪt/', 'B2', 'noun', 'nét tiêu biểu, đặc điểm', 'a particular quality or characteristic that belongs to a person\'s character or personality.', 'Leadership is a key trait for this position.', 'Khả năng lãnh đạo là một đặc điểm quan trọng cho vị trí này.', '{\"en\": \"Strong communication skills are considered a key trait for successful project managers.\", \"vi\": \"Kỹ năng giao tiếp tốt được coi là một đặc điểm then chốt của các quản lý dự án thành công.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/trait-ljspeech-28257104.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/trait-cori-28257104.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/trait-ee3c503b.webp', '[\"characteristic\", \"feature\", \"quality\", \"attribute\"]', NULL, '[{\"phrase\": \"personality trait\", \"meaning\": \"nét tính cách\"}, {\"phrase\": \"leadership trait\", \"meaning\": \"đặc điểm lãnh đạo\"}]', '[{\"word\": \"trace\", \"note_vi\": \"trace (n/v) có nghĩa là dấu vết hoặc truy vết.\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/trait-cori-28257104.mp3\", \"/storage/v1/object/public/pronunciation/v2/trait-aru0-28257104.mp3\", \"/storage/v1/object/public/pronunciation/v2/trait-aru5-28257104.mp3\", \"/storage/v1/object/public/pronunciation/v2/trait-aru6-28257104.mp3\", \"/storage/v1/object/public/pronunciation/v2/trait-aru10-28257104.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/trait-aru9-28257104.mp3\", \"/storage/v1/object/public/pronunciation/v2/trait-aru3-28257104.mp3\", \"/storage/v1/object/public/pronunciation/v2/trait-aru7-28257104.mp3\", \"/storage/v1/object/public/pronunciation/v2/trait-aru8-28257104.mp3\", \"/storage/v1/object/public/pronunciation/v2/trait-aru2-28257104.mp3\"]}, \"us\": {\"nu\": [\