('7042372c-5dac-505a-afd9-c2f4d7a8551a', '51593eab-afc9-5ad7-9776-2e5deeada393', 'de992005-e073-5a03-ba9f-972cc9368b00', 'a47516a3-b7ab-5758-afc0-c40e68514eae', 'courier', '/ˈkʊriə(r)/', 'B2', 'noun', 'người hoặc công ty chuyên vận chuyển thư từ, bưu kiện.', 'a person or company that is paid to deliver letters or packages to people.', 'We sent the urgent documents via a reliable courier service.', 'Chúng tôi đã gửi các tài liệu khẩn cấp qua một dịch vụ chuyển phát đáng tin cậy.', '{\"en\": \"Please ensure the courier delivers the signed contract to our headquarters before the business day ends.\", \"vi\": \"Vui lòng đảm bảo người chuyển phát giao hợp đồng đã ký đến trụ sở chúng tôi trước khi hết ngày làm việc.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/courier-ljspeech-023daeb6.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/courier-cori-023daeb6.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/courier-d3e13e61.webp', '[\"messenger\", \"delivery person\"]', NULL, '[{\"phrase\": \"courier service\", \"meaning\": \"dịch vụ chuyển phát\"}, {\"phrase\": \"express courier\", \"meaning\": \"chuyển phát nhanh\"}]', '[{\"word\": \"carrier\", \"note_vi\": \"Carrier là hãng vận tải lớn, courier thường là người/công ty giao nhận nhanh.\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/courier-cori-023daeb6.mp3\", \"/storage/v1/object/public/pronunciation/v2/courier-aru0-023daeb6.mp3\", \"/storage/v1/object/public/pronunciation/v2/courier-aru5-023daeb6.mp3\", \"/storage/v1/object/public/pronunciation/v2/courier-aru6-023daeb6.mp3\", \"/storage/v1/object/public/pronunciation/v2/courier-aru10-023daeb6.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/courier-aru9-023daeb6.mp3\", \"/storage/v1/object/public/pronunciation/v2/courier-aru3-023daeb6.mp3\", \"/storage/v1/object/public/pronunciation/v2/courier-aru7-023daeb6.mp3\", \"/storage/v1/object/public/pronunciation/v2/courier-aru8-023dae