('53bf5507-3f21-52b9-a369-e4ca442142cb', '51593eab-afc9-5ad7-9776-2e5deeada393', 'e37df36c-df41-5c6d-a061-1e44113885c9', 'a74f7bf4-eb16-5de3-8c5b-d30ed9053e53', 'approach', 'UK: /əˈprəʊtʃ/ | US: /əˈproʊtʃ/', 'B2', 'verb', 'tiếp cận, xử lý', 'To deal with or address a task, situation, or problem directly.', 'Please approach the new project with caution.', 'Hãy tiếp cận dự án mới một cách thận trọng.', '{\"en\": \"Our consulting firm will approach the marketing issue from a new perspective.\", \"vi\": \"Công ty tư vấn của chúng tôi sẽ xử lý vấn đề tiếp thị từ một góc nhìn mới.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/approach-ljspeech-119e99d8.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/approach-cori-119e99d8.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/approach-746c2c9b.webp', '[\"tackle\", \"address\", \"handle\"]', '[\"ignore\", \"avoid\"]', '[{\"phrase\": \"approach a problem\", \"meaning\": \"tiếp cận/xử lý một vấn đề\"}, {\"phrase\": \"cautiously approach\", \"meaning\": \"tiếp cận một cách thận trọng\"}]', NULL, '[{\"pos\": \"noun\", \"word\": \"approach\"}, {\"pos\": \"adjective\", \"word\": \"approachable\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/approach-cori-119e99d8.mp3\", \"/storage/v1/object/public/pronunciation/v2/approach-aru0-119e99d8.mp3\", \"/storage/v1/object/public/pronunciation/v2/approach-aru5-119e99d8.mp3\", \"/storage/v1/object/public/pronunciation/v2/approach-aru6-119e99d8.mp3\", \"/storage/v1/object/public/pronunciation/v2/approach-aru10-119e99d8.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/approach-aru9-119e99d8.mp3\", \"/storage/v1/object/public/pronunciation/v2/approach-aru3-119e99d8.mp3\", \"/storage/v1/object/public/pronunciation/v2/approach-aru7-119e99d8.mp3\", \"/storage/v1/object/public/pronunciation/v2/approach-aru8-119e99d8.mp3\", \"/storage/v1/object/public/pronunciation/v2/approach-aru2-119e99d8.mp3\"]}, \"us\": {\"nu\"