('14e777cb-ae2e-58cc-9e5f-1e2b6e5018a4', '51593eab-afc9-5ad7-9776-2e5deeada393', 'e738fd10-f5de-528b-8706-ba8f1ad107d5', '962b4086-5c66-500b-8685-9928699d76ce', 'deliver', 'UK: /dɪˈlɪvə/ | US: /dɪˈlɪvər/', 'B1', 'verb', 'giao hàng', 'To take goods, letters, or packages to a specified destination or person.', 'We deliver packages to customers daily.', 'Chúng tôi giao các gói hàng cho khách hàng hàng ngày.', '{\"en\": \"The courier company promised to deliver the contract to the client by 5 p.m.\", \"vi\": \"Công ty chuyển phát nhanh hứa sẽ giao hợp đồng cho khách hàng trước 5 giờ chiều.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/deliver-ljspeech-c3a71b15.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/deliver-cori-c3a71b15.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/deliver-7b063808.webp', '[\"transport\", \"dispatch\", \"bring\", \"hand over\"]', '[\"receive\", \"collect\"]', '[{\"phrase\": \"deliver goods\", \"meaning\": \"giao hàng hóa\"}, {\"phrase\": \"deliver a presentation\", \"meaning\": \"trình bày bài thuyết trình\"}, {\"phrase\": \"deliver on time\", \"meaning\": \"giao hàng đúng giờ\"}]', NULL, '[{\"pos\": \"noun\", \"word\": \"delivery\"}, {\"pos\": \"noun\", \"word\": \"deliverer\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/deliver-cori-c3a71b15.mp3\", \"/storage/v1/object/public/pronunciation/v2/deliver-aru0-c3a71b15.mp3\", \"/storage/v1/object/public/pronunciation/v2/deliver-aru5-c3a71b15.mp3\", \"/storage/v1/object/public/pronunciation/v2/deliver-aru6-c3a71b15.mp3\", \"/storage/v1/object/public/pronunciation/v2/deliver-aru10-c3a71b15.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/deliver-aru9-c3a71b15.mp3\", \"/storage/v1/object/public/pronunciation/v2/deliver-aru3-c3a71b15.mp3\", \"/storage/v1/object/public/pronunciation/v2/deliver-aru7-c3a71b15.mp3\", \"/storage/v1/object/public/pronunciation/v2/deliver-aru8-c3a71b15.mp3\", \"/storage/v1/object/pub