('a186b413-4892-5736-81ca-43ee378169b9', '51593eab-afc9-5ad7-9776-2e5deeada393', 'ed49bd0a-32de-57f4-9496-85a1965a7eca', '3e817b9d-cc63-5a6c-a7c3-a5bf893ba05e', 'disembark', '/ˌdɪsɪmˈbɑːk/', 'C1', 'verb', 'Rời khỏi tàu, máy bay hoặc phương tiện giao thông khác.', 'to leave a ship, aircraft, or other vehicle after a journey.', 'Passengers are requested to disembark from the train carefully when it reaches the final station.', 'Hành khách được yêu cầu xuống tàu cẩn thận khi tàu đến ga cuối.', '{\"en\": \"Passengers must show their boarding passes before they disembark from the cruise ship.\", \"vi\": \"Hành khách phải trình thẻ lên tàu trước khi xuống tàu du lịch.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/disembark-ljspeech-cead2375.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/disembark-cori-cead2375.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/disembark-e9373c7f.webp', '[\"alight\", \"get off\", \"deplane\"]', '[\"embark\", \"board\"]', '[{\"phrase\": \"disembark from a plane\", \"meaning\": \"xuống máy bay\"}, {\"phrase\": \"disembark passengers\", \"meaning\": \"cho hành khách xuống tàu/xe\"}]', '[{\"word\": \"embark\", \"note_vi\": \"Embark là lên tàu/máy bay, ngược nghĩa với disembark.\"}]', '[{\"pos\": \"noun\", \"word\": \"disembarkation\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/disembark-cori-cead2375.mp3\", \"/storage/v1/object/public/pronunciation/v2/disembark-aru0-cead2375.mp3\", \"/storage/v1/object/public/pronunciation/v2/disembark-aru5-cead2375.mp3\", \"/storage/v1/object/public/pronunciation/v2/disembark-aru6-cead2375.mp3\", \"/storage/v1/object/public/pronunciation/v2/disembark-aru10-cead2375.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/disembark-aru9-cead2375.mp3\", \"/storage/v1/object/public/pronunciation/v2/disembark-aru3-cead2375.mp3\", \"/storage/v1/object/public/pronunciation/v2/disembark-aru7-cead2375.mp3\", \"/storage/v1/object/public/