('3a88ea8e-45f1-56fb-ac3f-5b5f671747a7', '51593eab-afc9-5ad7-9776-2e5deeada393', 'ed49bd0a-32de-57f4-9496-85a1965a7eca', '3e817b9d-cc63-5a6c-a7c3-a5bf893ba05e', 'usher', 'UK: /ˈʌʃ.ər/ | US: /ˈʌʃ.ər/', 'B2', 'noun', 'người dẫn chỗ', 'a person who shows people to their assigned seats in a public building.', 'The usher led us to our assigned seats.', 'Người dẫn chỗ dẫn chúng tôi đến ghế đã được chỉ định.', '{\"en\": \"An usher guided the international delegates to their reserved seats in the main conference hall.\", \"vi\": \"Một người dẫn chỗ đã hướng dẫn các đại biểu quốc tế đến vị trí ghế dành riêng cho họ trong hội trường chính.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/usher-ljspeech-58a7a532.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/usher-cori-58a7a532.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/usher-ebb41071.webp', '[\"guide\", \"attendant\", \"escort\"]', NULL, '[{\"phrase\": \"event usher\", \"meaning\": \"nhân viên hướng dẫn chỗ ngồi sự kiện\"}, {\"phrase\": \"usher someone to a seat\", \"meaning\": \"dẫn ai đó tới chỗ ngồi\"}]', '[{\"word\": \"host\", \"note_vi\": \"người chủ trì/đón tiếp tổng thể, không phụ trách cụ thể việc đưa khách vào chỗ ngồi như usher\"}]', '[{\"pos\": \"verb\", \"word\": \"usher\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/usher-cori-58a7a532.mp3\", \"/storage/v1/object/public/pronunciation/v2/usher-aru0-58a7a532.mp3\", \"/storage/v1/object/public/pronunciation/v2/usher-aru5-58a7a532.mp3\", \"/storage/v1/object/public/pronunciation/v2/usher-aru6-58a7a532.mp3\", \"/storage/v1/object/public/pronunciation/v2/usher-aru10-58a7a532.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/usher-aru9-58a7a532.mp3\", \"/storage/v1/object/public/pronunciation/v2/usher-aru3-58a7a532.mp3\", \"/storage/v1/object/public/pronunciation/v2/usher-aru7-58a7a532.mp3\", \"/storage/v1/object/public/pronunciation/v2/usher-aru8-58a7a532.mp3\", \"/storage/v1/o