('bd2394ae-ac30-5b67-a8d9-400ed209c065', '51593eab-afc9-5ad7-9776-2e5deeada393', 'f7be4afb-660e-54bf-b271-cf07194857bd', 'a6421abb-9cc7-5e96-ba5b-45f6b41b1057', 'convert', 'UK: /kənˈvɜːt/ | US: /kənˈvɜːrt/', 'B2', 'verb', 'chuyển đổi', 'to change something from one form, purpose, or system into a different one.', 'The old factory was converted into modern apartments.', 'Nhà máy cũ đã được chuyển đổi thành các căn hộ hiện đại.', '{\"en\": \"The IT department is working to convert all paper records into digital files.\", \"vi\": \"Bộ phận CNTT đang làm việc để chuyển đổi tất cả hồ sơ giấy thành các tệp kỹ thuật số.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/convert-ljspeech-20a70aaf.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/convert-cori-20a70aaf.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/convert-a30dabdf.webp', '[\"transform\", \"change\", \"alter\", \"switch\"]', '[\"keep\", \"maintain\"]', '[{\"phrase\": \"convert currency\", \"meaning\": \"đổi tiền tệ\"}, {\"phrase\": \"convert A into B\", \"meaning\": \"chuyển đổi A thành B\"}]', '[{\"word\": \"convey\", \"note_vi\": \"Truyền tải thông điệp/cảm xúc, khác với convert là chuyển đổi dạng thức/hệ thống.\"}]', '[{\"pos\": \"noun\", \"word\": \"conversion\"}, {\"pos\": \"adjective\", \"word\": \"convertible\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/convert-cori-20a70aaf.mp3\", \"/storage/v1/object/public/pronunciation/v2/convert-aru0-20a70aaf.mp3\", \"/storage/v1/object/public/pronunciation/v2/convert-aru5-20a70aaf.mp3\", \"/storage/v1/object/public/pronunciation/v2/convert-aru6-20a70aaf.mp3\", \"/storage/v1/object/public/pronunciation/v2/convert-aru10-20a70aaf.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/convert-aru9-20a70aaf.mp3\", \"/storage/v1/object/public/pronunciation/v2/convert-aru3-20a70aaf.mp3\", \"/storage/v1/object/public/pronunciation/v2/convert-aru7-20a70aaf.mp3\", \"/storage/v1/object/public/p